} from './chart-scale-normalizer';

describe('[SUBETAPA 01] Normalização de Escala, Sementes e Prevenção de Velas Gigantes / Gaps', () => {
  const sampleCandles: Candle[] = [
    { time: 1700000000, open: '1.0800', high: '1.0820', low: '1.0790', close: '1.0810', volume: 50 },
    { time: 1700000060, open: '1.0810', high: '1.0830', low: '1.0805', close: '1.0825', volume: 60 },
    { time: 1700000120, open: '1.0825', high: '1.0840', low: '1.0820', close: '1.0835', volume: 70 },
  ];

  it('NORM-01: Ancoragem Suave: Ajusta a última vela da semente se o primeiro tick real divergir suavemente', () => {
    // O último candle do seed fechou em 1.0835. O primeiro tick real chega em 1.0838.
    const tick: Tick = {
      type: 'tick',
      sequence: 1,
      symbol: 'EURUSD_OTC',
      price: '1.0838',
      ts: new Date(1700000140 * 1000).toISOString(),
    };

    const normalized = normalizeSeedWithTick(sampleCandles, tick);
    expect(normalized).toHaveLength(3);
    const last = normalized[2];
    expect(Number(last.close)).toBeCloseTo(1.0838, 4);
    expect(Number(last.high)).toBeGreaterThanOrEqual(1.0838);
    expect(Number(last.low)).toBeLessThanOrEqual(1.0838);
  });

  it('NORM-02: Prevenção de Vela Gigante: Quando há salto estocástico irracional (>3%), renormaliza toda a semente para o nível de preço real', () => {
    // Semente estava em ~1.08, mas o ativo na verdade está cotado em 1.15 (ou tick real está em 1.15)
    const tick: Tick = {
      type: 'tick',
      sequence: 2,
      symbol: 'EURUSD_OTC',
      price: '1.1500',
      ts: new Date(1700000140 * 1000).toISOString(),
    };

    const normalized = normalizeSeedWithTick(sampleCandles, tick);
    const last = normalized[normalized.length - 1];

    // O último fechamento deve estar alinhado com o tick real sem criar um pavio absurdo
    expect(Number(last.close)).toBeCloseTo(1.1500, 4);
    // A amplitude da vela (high - low) não pode ser o salto absurdo de (1.15 - 1.08) = 0.07!
    const candleSpread = Number(last.high) - Number(last.low);
    expect(candleSpread).toBeLessThan(0.01); // Mantém volatilidade realista
  });

  it('NORM-03: Alinhamento de Gap Temporal: Garante que a semente não deixe um buraco de minutos até o primeiro tick', () => {
    // Tick chega 300 segundos após o último candle
    const futureTick: Tick = {
      type: 'tick',
      sequence: 3,
      symbol: 'EURUSD_OTC',
      price: '1.0840',
      ts: new Date((1700000120 + 300) * 1000).toISOString(),
    };

    const normalized = normalizeSeedWithTick(sampleCandles, futureTick);
    expect(normalized.length).toBeGreaterThanOrEqual(sampleCandles.length);
    const last = normalized[normalized.length - 1];
    expect(Number(last.time)).toBe(1700000120 + 300);
  });

  it('NORM-04: safeCandleFromTick descarta ticks corrompidos, NaN, ou com timestamp invertido', () => {
    const prevCandle = {
      time: 1700000120 as any,
      open: 1.0825,
      high: 1.0840,
      low: 1.0820,
      close: 1.0835,
    };

    // Preço inválido
    expect(safeCandleFromTick({ type: 'tick', sequence: 1, symbol: 'EURUSD_OTC', price: 'NaN', ts: '2026-01-01' }, prevCandle, '1m')).toBeNull();
    expect(safeCandleFromTick({ type: 'tick', sequence: 2, symbol: 'EURUSD_OTC', price: '-10', ts: '2026-01-01' }, prevCandle, '1m')).toBeNull();

    // Timestamp inválido
    expect(safeCandleFromTick({ type: 'tick', sequence: 3, symbol: 'EURUSD_OTC', price: '1.0840', ts: 'invalido' }, prevCandle, '1m')).toBeNull();

    // Timestamp no passado
    expect(safeCandleFromTick({ type: 'tick', sequence: 4, symbol: 'EURUSD_OTC', price: '1.0840', ts: new Date(1600000000 * 1000).toISOString() }, prevCandle, '1m')).toBeNull();
  });

  it('NORM-05: detectPriceScaleAnomaly acusa transição abrupta de ordem de magnitude (ex: BTC 64.000 -> EURUSD 1.08)', () => {
    // Mudança de 64.000 para 1.085 é anomalia de escala extrema
    const isAnomaly = detectPriceScaleAnomaly(64850.0, 1.0854);
    expect(isAnomaly).toBe(true);

    // Variação normal de 1.0850 para 1.0860 NÃO é anomalia
    const isNormal = detectPriceScaleAnomaly(1.0850, 1.0860);
    expect(isNormal).toBe(false);
  });

  it('NORM-06: Teste de Estresse: 5.000 atualizações consecutivas de ticks mantém velas dentro dos limites matemáticos', () => {
    let current = {
      time: 1700000000 as any,
      open: 100.0,
      high: 100.0,
      low: 100.0,
      close: 100.0,
    };

    let price = 100.0;
    for (let i = 1; i <= 5000; i++) {
      const delta = (Math.sin(i) * 0.5);
      price = Math.max(1.0, price + delta);
      const tick: Tick = {
        type: 'tick',
        sequence: i,
        symbol: 'SYNTH_VOL_50',
        price: price.toFixed(4),
        ts: new Date((1700000000 + Math.floor(i / 10)) * 1000).toISOString(),
      };

      const updated = safeCandleFromTick(tick, current, '1m');
      if (updated) {
        current = updated;
        const bounds = calculateSafeCandleBounds(updated);
        expect(bounds.isValid).toBe(true);
        expect(bounds.spreadPercent).toBeLessThan(10); // Nunca explode mais de 10% na mesma vela de 1m
      }
    }
  });
});

import type { DrawingItem } from './drawing-types';

const VALID_DRAWING_TYPES = new Set([
  'line',
  'trend_line',
  'horizontal_line',
  'vertical_line',
  'fibonacci',
]);

const SAFE_COLOR_REGEX = /^#([0-9a-fA-F]{3,8})$|^rgba?\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*(?:,\s*[\d.]+\s*)?\)$/;

/**
 * Valida e sanitiza um item geométrico de desenho individual.
 * Descarta coordenadas corrompidas (NaN, Infinity, preços <= 0) e sanitiza cores contra injection.
 */
export function validateDrawingItem(raw: unknown): DrawingItem | null {
  if (!raw || typeof raw !== 'object') return null;

  const item = raw as Partial<DrawingItem>;

  if (typeof item.id !== 'string' || !item.id.trim()) return null;
  if (!item.type || !VALID_DRAWING_TYPES.has(item.type)) return null;

  // Validação estrita do Ponto 1 (p1)
  if (!item.p1 || typeof item.p1 !== 'object') return null;
  const p1Time = Number(item.p1.time);
  const p1Price = Number(item.p1.price);

  if (!Number.isFinite(p1Time) || p1Time <= 0 || !Number.isFinite(p1Price) || p1Price <= 0) {
    return null;
  }

  // Validação do Ponto 2 (p2) caso exista
  let safeP2 = undefined;
  if (item.p2 && typeof item.p2 === 'object') {
    const p2Time = Number(item.p2.time);
    const p2Price = Number(item.p2.price);
    if (Number.isFinite(p2Time) && p2Time > 0 && Number.isFinite(p2Price) && p2Price > 0) {
      safeP2 = {
        time: p2Time as any,
        price: p2Price,
        logical: typeof item.p2.logical === 'number' && Number.isFinite(item.p2.logical) ? item.p2.logical : undefined,
      };
    }
  }

  // Sanitização de cor
  let safeColor = '#22C47A';
  if (typeof item.color === 'string' && SAFE_COLOR_REGEX.test(item.color.trim())) {
    safeColor = item.color.trim();
  }

  // Sanitização de largura de traço (clamped entre 1 e 8)
  const rawWidth = Number(item.lineWidth);
  const safeWidth = Number.isFinite(rawWidth) ? Math.max(1, Math.min(8, Math.round(rawWidth))) : 1;

  return {
    id: item.id.trim(),
    type: item.type,
    p1: {
      time: p1Time as any,
      price: p1Price,
      logical: typeof item.p1.logical === 'number' && Number.isFinite(item.p1.logical) ? item.p1.logical : undefined,
    },
    p2: safeP2,
    color: safeColor,
    lineWidth: safeWidth,
    label: typeof item.label === 'string' ? item.label.slice(0, 32) : undefined,
  };
}

function getStorage(): Storage | null {
  if (typeof window !== 'undefined' && window.localStorage) {
    return window.localStorage;
  }
  if (typeof globalThis !== 'undefined' && (globalThis as any).localStorage) {
    return (globalThis as any).localStorage;
  }
  return null;
}

/**
 * Carrega desenhos persistidos para o ativo de forma 100% segura.
 * Nunca lança exceção em JSON corrompido ou entradas inválidas.
 */
export function loadSafeDrawings(symbol: string): DrawingItem[] {
  const storage = getStorage();
  if (!storage) return [];

  try {
    const raw = storage.getItem('broker_drawings_' + symbol);
    if (!raw) return [];

    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];

    const clean: DrawingItem[] = [];
    for (const item of parsed) {
      const valid = validateDrawingItem(item);
      if (valid) {
        clean.push(valid);
      }
    }
    return clean;
  } catch {
    return [];
  }
}

/**
 * Salva desenhos no localStorage com proteção contra estouro de cota (QuotaExceededError).
 */
export function saveSafeDrawings(symbol: string, drawings: DrawingItem[]): void {
  const storage = getStorage();
  if (!storage) return;

  try {
    const cleanDrawings = drawings
      .map(validateDrawingItem)
      .filter((d): d is DrawingItem => d !== null);

    storage.setItem('broker_drawings_' + symbol, JSON.stringify(cleanDrawings));
  } catch (err: unknown) {
    // Se a cota do localStorage estourar, limpa chaves de desenhos antigas de outros símbolos
    if (err instanceof Error && (err.name === 'QuotaExceededError' || err.name === 'NS_ERROR_DOM_QUOTA_REACHED')) {
      console.warn('[DrawingSanitizer] LocalStorage Quota Exceeded — limpando cache de desenhos de outros ativos');
      try {
        for (let i = storage.length - 1; i >= 0; i--) {
          const key = storage.key(i);
          if (key && key.startsWith('broker_drawings_') && key !== 'broker_drawings_' + symbol) {
            storage.removeItem(key);
          }
        }
        storage.setItem('broker_drawings_' + symbol, JSON.stringify(drawings));
      } catch {
        // Falha silenciosa defensiva
      }
    }
  }
}

