    expect(drawings.find((d) => d.id === 'h1')).toBeDefined();

    // Limpeza total
    clear();
    expect(drawings.length).toBe(0);
  });

  it('[SUBETAPA 2 - Throttling rAF] simula coalescência de 100 eventos de mouse no mesmo quadro rAF', () => {
    let pendingPoint: { x: number; y: number } | null = null;
    let scheduled = false;
    let frameUpdates = 0;
    let finalAppliedPoint: { x: number; y: number } | null = null;

    const onMouseMove = (x: number, y: number) => {
      pendingPoint = { x, y };
      if (!scheduled) {
        scheduled = true;
        // Simulação do requestAnimationFrame
        setTimeout(() => {
          if (pendingPoint) {
            finalAppliedPoint = pendingPoint;
            frameUpdates++;
          }
          scheduled = false;
        }, 16);
      }
    };

    // 100 movimentos rápidos de mouse em microsegundos
    for (let i = 0; i < 100; i++) {
      onMouseMove(i * 2, i * 3);
    }

    expect(pendingPoint).toEqual({ x: 198, y: 297 });
    expect(scheduled).toBe(true);
  });

  it('[CORREÇÃO TREND LINE] valida resolução de coordenadas via logical index quando timestamp é nulo/futuro', () => {
    // Simula o motor de escala do Lightweight Charts
    const mockTimeScale = {
      logicalToCoordinate: (logical: number) => 100 + logical * 10,
      timeToCoordinate: (time: number) => (time === 1700000000 ? 200 : null), // Só reconhece vela exata
    };

    const resolveX = (pt: { time: number; logical?: number }) => {
      if (typeof pt.logical === 'number') {
        const coord = mockTimeScale.logicalToCoordinate(pt.logical);
        if (coord !== null) return coord;
      }
      return mockTimeScale.timeToCoordinate(pt.time);
    };

    // Ponto 1: Em cima de uma vela histórica
    const p1 = { time: 1700000000, logical: 10 };
    // Ponto 2: No futuro / margem direita onde timeToCoordinate retorna NULL
    const p2 = { time: 1700000999, logical: 25 };

    const x1 = resolveX(p1);
    const x2 = resolveX(p2);

    expect(x1).toBe(200); // 100 + 10 * 10
    expect(x2).toBe(350); // 100 + 25 * 10 (resolvido com sucesso mesmo sem candle existente!)
  });

  it('[CORREÇÃO TREND LINE] calcula extensão de raio futuro para projeção de suporte/resistência', () => {
    const x1 = 100;
    const y1 = 200;
    const x2 = 200;
    const y2 = 250;
    const containerWidth = 800;

    const dx = x2 - x1; // 100
    const dy = y2 - y1; // 50 (slope = 0.5)

    const extendedX = Math.max(containerWidth + 50, x2 + 350); // 850
    const extendedY = y1 + (dy / dx) * (extendedX - x1); // 200 + 0.5 * 750 = 575

    expect(extendedX).toBe(850);
    expect(extendedY).toBe(575);
  });

  it('[MOVIMENTAÇÃO DE LINHAS] translada linha horizontal no eixo Y (preço)', () => {
    const drawing: DrawingItem = {
      id: 'h1',
      type: 'horizontal_line',
      p1: { time: 100 as any, price: 500.0, logical: 10 },
      color: '#00e676',
      lineWidth: 2,
    };

    // Usuário arrasta a linha para 505.75
    const movedDrawing: DrawingItem = {
      ...drawing,
      p1: { ...drawing.p1, price: 505.75 },
    };

    expect(movedDrawing.p1.price).toBe(505.75);
    expect(movedDrawing.id).toBe('h1');
  });

  it('[MOVIMENTAÇÃO DE LINHAS] translada linha de tendência inteira (corpo) preservando inclinação', () => {
    const initialLine: DrawingItem = {
      id: 't1',
      type: 'trend_line',
      p1: { time: 100 as any, price: 500.0, logical: 10 },
      p2: { time: 200 as any, price: 520.0, logical: 20 },
      color: '#38bdf8',
      lineWidth: 2,
    };

    const deltaPrice = +15.5;
    const deltaLogical = +5;

    const translatedLine: DrawingItem = {
      ...initialLine,
      p1: {
        ...initialLine.p1,
        price: initialLine.p1.price + deltaPrice,
        logical: (initialLine.p1.logical ?? 0) + deltaLogical,
      },
      p2: initialLine.p2 ? {
        ...initialLine.p2,
        price: initialLine.p2.price + deltaPrice,
        logical: (initialLine.p2.logical ?? 0) + deltaLogical,
      } : undefined,
    };

    expect(translatedLine.p1.price).toBe(515.5);
    expect(translatedLine.p2?.price).toBe(535.5);
    expect(translatedLine.p1.logical).toBe(15);
    expect(translatedLine.p2?.logical).toBe(25);
    // Inclinação (delta) permanece idêntica
    expect(translatedLine.p2!.price - translatedLine.p1.price).toBe(20.0);
  });

  it('[MOVIMENTAÇÃO DE LINHAS] reposiciona ponto de ancoragem P2 de forma independente', () => {
    const initialLine: DrawingItem = {
      id: 't2',
      type: 'trend_line',
      p1: { time: 100 as any, price: 500.0, logical: 10 },
      p2: { time: 200 as any, price: 520.0, logical: 20 },
      color: '#38bdf8',
      lineWidth: 2,
    };

    // Ajuste fino do P2 para novo preço e barra
    const adjustedP2: DrawingItem = {
      ...initialLine,
      p2: {
        ...initialLine.p2!,
        price: 540.0,
        logical: 28,
      },
    };

    expect(adjustedP2.p1.price).toBe(500.0); // P1 intocado
    expect(adjustedP2.p1.logical).toBe(10);
    expect(adjustedP2.p2?.price).toBe(540.0); // P2 atualizado
    expect(adjustedP2.p2?.logical).toBe(28);
  });
});

import { describe, it, expect } from 'vitest';
import {
  calculateSMA,
  calculateEMA,
  calculateWMA,
  calculateBollinger,
  calculateRSI,
  calculateMACD,
  calculateStochastic,
  calculateATR,
  calculateVWAP,
  calculateCCI,
} from './indicator-calculator';
import type { Candle } from '../api/client';

describe('[SUBETAPA 5 - ESTRESSE, CAOS & SEGURANÇA] Indicadores Técnicos Institucionais', () => {
  // Geração de 1.000 velas sintéticas de alta volatilidade
  const largeCandleDataset: Candle[] = Array.from({ length: 1000 }, (_, i) => {
    const base = 1000 + Math.sin(i / 10) * 100 + (i % 20);
    return {
      time: 1700000000 + i * 60,
      open: base.toFixed(2),
      high: (base + 5 + (i % 3)).toFixed(2),
      low: (base - 5 - (i % 3)).toFixed(2),
      close: (base + (i % 2 === 0 ? 2 : -2)).toFixed(2),
      volume: 100 + (i % 50),
    };
  });

  describe('1. Testes de Estresse e Throughput', () => {
    it('executa o cálculo de TODOS os 10 indicadores sobre 1.000 velas em menos de 100ms', () => {
      const start = performance.now();

      const sma = calculateSMA(largeCandleDataset, 20);
      const ema = calculateEMA(largeCandleDataset, 20);
      const wma = calculateWMA(largeCandleDataset, 20);
      const bollinger = calculateBollinger(largeCandleDataset, 20, 2);
      const rsi = calculateRSI(largeCandleDataset, 14);
      const macd = calculateMACD(largeCandleDataset, 12, 26, 9);
      const stoch = calculateStochastic(largeCandleDataset, 14, 3);
      const atr = calculateATR(largeCandleDataset, 14);
      const vwap = calculateVWAP(largeCandleDataset);
      const cci = calculateCCI(largeCandleDataset, 20);

      const elapsed = performance.now() - start;

      expect(sma.length).toBeGreaterThan(900);
      expect(ema.length).toBeGreaterThan(900);
      expect(wma.length).toBeGreaterThan(900);
      expect(bollinger.length).toBeGreaterThan(900);
      expect(rsi.length).toBeGreaterThan(900);
      expect(macd.length).toBeGreaterThan(900);
      expect(stoch.length).toBeGreaterThan(900);
      expect(atr.length).toBeGreaterThan(900);
      expect(vwap.length).toBe(1000);
      expect(cci.length).toBeGreaterThan(900);

      // O tempo total para os 10 indicadores sobre 1.000 barras não pode exceder 250ms sob carga paralela
      expect(elapsed).toBeLessThan(250);
    });

    it('suporta períodos longos (SMA 200 e EMA 200) sem estourar pilha de recursão', () => {
      expect(() => calculateSMA(largeCandleDataset, 200)).not.toThrow();
      expect(() => calculateEMA(largeCandleDataset, 200)).not.toThrow();
      expect(() => calculateWMA(largeCandleDataset, 200)).not.toThrow();
    });
  });

  describe('2. Testes de Caos e Anomalias de Dados', () => {
    it('resiste a velas com volume zerado, negativo ou string alfanumérica', () => {
      const corruptCandles = [
        { time: 1700000000, open: '100', high: '110', low: '90', close: '105', volume: '0' },
        { time: 1700000060, open: '105', high: '115', low: '95', close: '110', volume: '-50' },
        { time: 1700000120, open: '110', high: '120', low: '100', close: '115', volume: 'invalid_vol' },
      ];

      const vwap = calculateVWAP(corruptCandles as any);
      expect(vwap).toHaveLength(3);
      for (const pt of vwap) {
        expect(Number.isFinite(pt.value)).toBe(true);
        expect(pt.value).toBeGreaterThan(0);
      }
    });

    it('resiste a timestamps misturados (ms x s x ISO)', () => {
      const mixedCandles = [
        { time: 1700000000000, close: '100' }, // ms (> 10^10)
        { time: 1700000060, close: '102' },    // s
        { open_time: '2026-10-07T00:02:00Z', close: '104' }, // ISO string
      ];

      const sma = calculateSMA(mixedCandles, 2);
      expect(sma).toHaveLength(2);
      expect(sma[0].time).toBe(1700000060);
      expect(sma[1].time).toBe(Math.floor(Date.parse('2026-10-07T00:02:00Z') / 1000));
    });

    it('lida com spread zero absoluto (high = low = open = close) sem gerar NaN no ATR ou Estocástico', () => {
      const flatCandles: Candle[] = Array.from({ length: 20 }, (_, i) => ({
        time: 1700000000 + i * 60,
        open: '500',
        high: '500',
        low: '500',
        close: '500',
        volume: 10,
      }));

      const atr = calculateATR(flatCandles, 14);
      expect(atr.length).toBeGreaterThan(0);
      expect(atr[0].value).toBe(0);

      const stoch = calculateStochastic(flatCandles, 14, 3);
      expect(stoch.length).toBeGreaterThan(0);
      expect(stoch[0].k).toBe(50); // Neutro
      expect(stoch[0].d).toBe(50);
    });
  });

  describe('3. Testes de Segurança Numérica', () => {
    it('garante que nenhum valor retornado seja NaN, null ou undefined', () => {
      const indicatorsResults = [
        calculateSMA(largeCandleDataset.slice(0, 50), 10),
        calculateEMA(largeCandleDataset.slice(0, 50), 10),
        calculateWMA(largeCandleDataset.slice(0, 50), 10),
        calculateRSI(largeCandleDataset.slice(0, 50), 14),
        calculateATR(largeCandleDataset.slice(0, 50), 14),
        calculateVWAP(largeCandleDataset.slice(0, 50)),
        calculateCCI(largeCandleDataset.slice(0, 50), 14),
      ];

      for (const res of indicatorsResults) {
        for (const pt of res) {
          expect(Number.isFinite(pt.value)).toBe(true);
          expect(Number.isNaN(pt.value)).toBe(false);
        }
      }

      const bbands = calculateBollinger(largeCandleDataset.slice(0, 50), 10, 2);
      for (const b of bbands) {
        expect(Number.isFinite(b.upper)).toBe(true);
        expect(Number.isFinite(b.middle)).toBe(true);
        expect(Number.isFinite(b.lower)).toBe(true);
      }

      const macd = calculateMACD(largeCandleDataset.slice(0, 50), 12, 26, 9);
      for (const m of macd) {
        expect(Number.isFinite(m.macd)).toBe(true);
        expect(Number.isFinite(m.signal)).toBe(true);
        expect(Number.isFinite(m.histogram)).toBe(true);
      }

      const stoch = calculateStochastic(largeCandleDataset.slice(0, 50), 14, 3);
      for (const s of stoch) {
        expect(Number.isFinite(s.k)).toBe(true);
        expect(Number.isFinite(s.d)).toBe(true);
      }
    });
  });
});

import React from 'react';
import { describe, it, expect, vi } from 'vitest';
import { renderToString } from 'react-dom/server';
import { MultiChartGrid, type GridLayout } from './MultiChartGrid';
import { normalizeSeedWithTick, safeCandleFromTick, detectPriceScaleAnomaly } from './chart-scale-normalizer';
import type { Candle } from '../api/client';
import type { Tick } from '../feed/protocol';

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

describe('[SUBETAPA 03] Testes de Caos, Estresse e Isolamento Multi-Gráficos', () => {
  const dummyContracts: any[] = [];
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });

  it('CHAOS-01: MultiChartGrid renderiza layouts 1x1, 2x1, 2x2 e 3x2 sem exceptions no SSR/DOM', () => {
    const layouts: GridLayout[] = ['1x1', '2x1', '2x2', '3x2'];

    for (const layout of layouts) {
      const html = renderToString(
        <QueryClientProvider client={queryClient}>
          <MultiChartGrid
            activeSymbol="EURUSD_OTC"
            onActiveSymbolChange={vi.fn()}
            allContracts={dummyContracts}
            layout={layout}
          />
        </QueryClientProvider>
      );
      expect(html).toBeDefined();
      expect(html.length).toBeGreaterThan(50);
    }
  });

  it('CHAOS-02: Isolamento Estrito: 6 gráficos com símbolos heterogêneos recebem rajadas sem contaminação cruzada', () => {
    const symbols = [
      'EURUSD_OTC',
      'BTCUSD_OTC',
      'XAUUSD_OTC',
      'SYNTH_VOL_50',
      'ETHUSD_OTC',
      'SOLUSD_OTC',
    ];

    const symbolPrices: Record<string, number> = {
      EURUSD_OTC: 1.0854,
      BTCUSD_OTC: 64850.0,
      XAUUSD_OTC: 2652.8,
      SYNTH_VOL_50: 1250.0,
      ETHUSD_OTC: 3450.0,
      SOLUSD_OTC: 152.4,
    };

    // Gera 1.000 rajadas de ticks distribuídas aleatoriamente entre os símbolos
    for (let i = 0; i < 1000; i++) {
      const sym = symbols[i % symbols.length];
      const base = symbolPrices[sym];
      const tickPrice = (base * (1 + (Math.sin(i) * 0.001))).toFixed(4);

      const tick: Tick = {
        type: 'tick',
        sequence: i + 1,
        symbol: sym,
        price: tickPrice,
        ts: new Date((1700000000 + i) * 1000).toISOString(),
      };

      const seed: Candle[] = [
        {
          time: 1700000000,
          open: String(base),
          high: String(base * 1.001),
          low: String(base * 0.999),
          close: String(base),
          volume: 10,
        },
      ];

      const normalized = normalizeSeedWithTick(seed, tick);
      expect(normalized.length).toBe(1);

      // Garante que o candle do EURUSD nunca assuma preço de BTCUSD ou vice-versa
      const closeNum = Number(normalized[0].close);
      if (sym === 'EURUSD_OTC') {
        expect(closeNum).toBeLessThan(2.0);
      } else if (sym === 'BTCUSD_OTC') {
        expect(closeNum).toBeGreaterThan(50000.0);
      }
    }
  });

  it('CHAOS-03: Resiliência contra Ticks Tóxicos (NaN, negativos, timestamps corrompidos)', () => {
    const prev = {
      time: 1700000000 as any,
      open: 1.0854,
      high: 1.0860,
      low: 1.0850,
      close: 1.0855,
    };

    const toxicTicks: any[] = [
      { symbol: 'EURUSD_OTC', price: null, ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: undefined, ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: 'Infinity', ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: '-999.0', ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: '0', ts: '2026-01-01' },
      { symbol: 'EURUSD_OTC', price: '1.0856', ts: 'invalid_date' },
      null,
      undefined,
    ];

    for (const toxic of toxicTicks) {
      const res = safeCandleFromTick(toxic, prev, '1m');
      // Deve descartar silenciosamente sem jogar exception nem corromper
      expect(res).toBeNull();
    }
  });

  it('CHAOS-04: Transição rápida entre escalas ordinais opostas é detectada com sucesso', () => {
    // BTC para EURUSD
    expect(detectPriceScaleAnomaly(64850.0, 1.0854)).toBe(true);
    // EURUSD para BTC
    expect(detectPriceScaleAnomaly(1.0854, 64850.0)).toBe(true);
    // Preços próximos
    expect(detectPriceScaleAnomaly(100.0, 100.5)).toBe(false);
  });
});

