      time: 1700000000 as any,
      open: 500.125,
      high: 500.125,
      low: 500.125,
      close: 500.125,
    };

    let price = 500.125;
    for (let i = 1; i <= 10000; i++) {
      price += (Math.sin(i * 0.1) * 0.05);
      const tick: Tick = {
        type: 'tick',
        sequence: i,
        symbol: 'SYNTH_VOL_50',
        price: price.toFixed(4),
        ts: new Date((1700000000 + Math.floor(i / 10)) * 1000).toISOString(),
