import React, { useEffect, useRef } from "react";
import { createChart, IChartApi, ISeriesApi, CandlestickData, Time } from "lightweight-charts";

interface TradingViewCanvasProps {
  symbol: string;
  lastTick: { sequence: string; price: string; ts: string } | null;
  activeContractPrice?: number | null;
}

export const TradingViewCanvas: React.FC<TradingViewCanvasProps> = ({
  symbol,
  lastTick,
  activeContractPrice
}) => {
  const chartContainerRef = useRef<HTMLDivElement>(null);
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ISeriesApi<"Candlestick"> | null>(null);
  const priceLineRef = useRef<any>(null);
  const lastSequenceRef = useRef<bigint>(0n);

  useEffect(() => {
    if (!chartContainerRef.current) return;

    const chart = createChart(chartContainerRef.current, {
      width: chartContainerRef.current.clientWidth,
      height: chartContainerRef.current.clientHeight,
      layout: {
        background: { color: "#0B0E14" },
        textColor: "#9B9FA4"
      },
      grid: {
        vertLines: { color: "#1E222D" },
        horzLines: { color: "#1E222D" }
      },
      timeScale: {
        timeVisible: true,
        secondsVisible: true,
        borderColor: "#2B2F3A"
      },
      rightPriceScale: {
        borderColor: "#2B2F3A"
      }
    });

    const candlestickSeries = chart.addCandlestickSeries({
      upColor: "#089981",
      downColor: "#F23645",
      borderVisible: false,
      wickUpColor: "#089981",
      wickDownColor: "#F23645"
    });

    chartRef.current = chart;
    seriesRef.current = candlestickSeries;

    // Carga de histórico inicial via REST UDF (D-03)
    const loadHistory = async () => {
      try {
        const to = Math.floor(Date.now() / 1000);
        const from = to - 3600; // Última 1 hora
        const res = await fetch(`/api/v1/chart/history?symbol=${symbol}&resolution=1&from=${from}&to=${to}`);
        const data = await res.json();

        if (data.s === "ok" && data.t) {
          const bars: CandlestickData[] = data.t.map((t: number, i: number) => ({
            time: t as Time,
            open: data.o[i],
            high: data.h[i],
            low: data.l[i],
            close: data.c[i]
          }));
          candlestickSeries.setData(bars);
        }
      } catch (err) {
        console.error("Failed to load chart history:", err);
      }
    };

    loadHistory();

    const handleResize = () => {
      if (chartContainerRef.current && chartRef.current) {
        chartRef.current.applyOptions({
          width: chartContainerRef.current.clientWidth,
          height: chartContainerRef.current.clientHeight
        });
      }
    };

    const resizeObserver = new ResizeObserver(handleResize);
    resizeObserver.observe(chartContainerRef.current);

    return () => {
      resizeObserver.disconnect();
      chart.remove();
    };
  }, [symbol]);

  // Atualização em tempo real da vela atual com o tick recebido via WebSocket
  useEffect(() => {
    if (!lastTick || !seriesRef.current) return;

    const seq = BigInt(lastTick.sequence);
    // Descarte rigoroso de ticks fora de ordem ou duplicados (F-06)
    if (seq <= lastSequenceRef.current) {
      return;
    }
    lastSequenceRef.current = seq;

    const tickTimeSec = Math.floor(new Date(lastTick.ts).getTime() / 1000);
    // Alinhamento ao bucket de 1 minuto em segundos
    const candleTimeSec = Math.floor(tickTimeSec / 60) * 60;
    const price = parseFloat(lastTick.price);

    seriesRef.current.update({
      time: candleTimeSec as Time,
      open: price,
      high: price,
      low: price,
      close: price
    });
  }, [lastTick]);

  // Atualiza linha de preço de entrada para ordens ativas
  useEffect(() => {
    if (!seriesRef.current) return;

    if (priceLineRef.current) {
      seriesRef.current.removePriceLine(priceLineRef.current);
      priceLineRef.current = null;
    }

    if (activeContractPrice) {
      priceLineRef.current = seriesRef.current.createPriceLine({
        price: activeContractPrice,
        color: "#F6C344",
        lineWidth: 2,
        lineStyle: 2, // Tracejado
        axisLabelVisible: true,
        title: "ENTRADA"
      });
    }
  }, [activeContractPrice]);

  return (
    <div
      ref={chartContainerRef}
      style={{
        width: "100%",
        height: "100%",
        position: "relative"
      }}
    />
  );
};

import { useEffect, useState } from 'react';
import type { Contract } from '../../api/client';
import { formatMinor } from '../../lib/money';
import { isNewTraderoomEnabled } from '../../lib/feature-flags';

export interface PortfolioDrawerProps {
  isOpen: boolean;
  onToggle: () => void;
  contracts: Contract[];
  currentPrice: number | string | null;
  currentSymbol: string;
}

export function PortfolioDrawer({
  isOpen,
  onToggle,
  contracts,
  currentPrice,
  currentSymbol,
}: PortfolioDrawerProps) {
  const [tab, setTab] = useState<'ACTIVE' | 'HISTORY'>('ACTIVE');
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 500);
    return () => clearInterval(timer);
  }, []);

  const openContracts = contracts.filter((c) => c.status === 'OPEN');
  const settledContracts = contracts.filter((c) => c.status !== 'OPEN');

  // Calcular PnL total potencial
  const potentialPnlMinor = openContracts.reduce((acc, c) => {
    const stake = typeof c.stake_minor === 'string' ? parseInt(c.stake_minor, 10) : c.stake_minor;
    return acc + Math.round(stake * 0.85);
  }, 0);

  const isBinmax = isNewTraderoomEnabled();

  return (
    <div
      className="portfolio-drawer-wrap"
      style={{
        display: 'flex',
        flexDirection: 'column',
        width: '100%',
        background: isBinmax ? '#151922' : '#0a101f',
        borderTop: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #1a253a',
        boxSizing: 'border-box',
      }}
    >
      {/* Barra de Rodapé Fixa (~30px) */}
      <div
        className="terminal-drawer-bar"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '0 16px',
          height: '30px',
          fontSize: '11px',
          color: isBinmax ? '#8A92A1' : '#8e9db7',
          cursor: 'pointer',
          userSelect: 'none',
        }}
        onClick={onToggle}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
            <span>💼</span>
            <strong style={{ color: isBinmax ? '#F4F5F7' : '#fff' }}>
              {isBinmax ? 'Portafolio total' : 'Portfólio Total'}
            </strong>
            <span
              style={{
                background: openContracts.length > 0 ? (isBinmax ? '#22C47A' : '#00e676') : (isBinmax ? '#0D0F14' : '#1c2d4a'),
                color: openContracts.length > 0 ? '#0D0F14' : '#8A92A1',
                borderRadius: '10px',
                padding: '1px 7px',
                fontSize: '10px',
                fontWeight: 800,
              }}
            >
              {openContracts.length} {isBinmax ? 'activas' : 'ativas'}
            </span>
          </div>

          {openContracts.length > 0 && (
            <span style={{ color: isBinmax ? '#22C47A' : '#00e676', fontWeight: 600 }}>
              {isBinmax ? 'Ganancia potencial' : 'Retorno potencial'}: +{formatMinor(potentialPnlMinor)}
            </span>
          )}
        </div>

        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onToggle();
          }}
          style={{
            background: isBinmax ? '#0D0F14' : '#131e33',
            border: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #253450',
            color: isBinmax ? '#DCE1EA' : '#bcd0ec',
            borderRadius: '4px',
            padding: '2px 10px',
            fontSize: '11px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
          }}
        >
          {isBinmax
            ? (isOpen ? 'Mostrar posiciones ⌃' : 'Mostrar posiciones ⌵')
            : (isOpen ? '▼ Ocultar Painel' : `▲ Expandir (${openContracts.length})`)}
        </button>
      </div>

      {/* Conteúdo Expandido da Gaveta (220px) */}
      {isOpen && (
        <div
          style={{
            height: '220px',
            maxHeight: '220px',
            background: '#090f1d',
            borderTop: '1px solid #162238',
            display: 'flex',
            flexDirection: 'column',
            boxSizing: 'border-box',
          }}
        >
          {/* Sub-abas da gaveta */}
          <div
            style={{
              display: 'flex',
              gap: '6px',
              padding: '8px 16px',
              borderBottom: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #162238',
              background: isBinmax ? '#0D0F14' : '#070c18',
            }}
          >
            <button
              type="button"
              onClick={() => setTab('ACTIVE')}
              style={{
                background: tab === 'ACTIVE' ? (isBinmax ? 'rgba(34, 196, 122, 0.15)' : '#192b49') : 'transparent',
                border: tab === 'ACTIVE' ? (isBinmax ? '1px solid #22C47A' : '1px solid #273e66') : '1px solid transparent',
                color: tab === 'ACTIVE' ? (isBinmax ? '#22C47A' : '#00e676') : '#8A92A1',
                borderRadius: '6px',
                padding: '4px 12px',
                fontSize: '11px',
                fontWeight: 700,
                cursor: 'pointer',
              }}
            >
              {isBinmax ? `Operaciones abiertas (${openContracts.length})` : `Operações Abertas (${openContracts.length})`}
            </button>
            <button
              type="button"
              onClick={() => setTab('HISTORY')}
              style={{
                background: tab === 'HISTORY' ? (isBinmax ? 'rgba(34, 196, 122, 0.15)' : '#192b49') : 'transparent',
                border: tab === 'HISTORY' ? (isBinmax ? '1px solid #22C47A' : '1px solid #273e66') : '1px solid transparent',
                color: tab === 'HISTORY' ? (isBinmax ? '#22C47A' : '#00e676') : '#8A92A1',
                borderRadius: '6px',
                padding: '4px 12px',
                fontSize: '11px',
                fontWeight: 700,
                cursor: 'pointer',
              }}
            >
              {isBinmax ? `Historial cerrado (${settledContracts.length})` : `Histórico Finalizado (${settledContracts.length})`}
            </button>
          </div>

          {/* Tabela de Operações */}
          <div style={{ flex: 1, overflowY: 'auto', padding: '0 16px' }}>
            {tab === 'ACTIVE' ? (
              openContracts.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '40px 0', color: '#8A92A1', fontSize: '12px' }}>
                  {isBinmax
                    ? 'Aún no tienes operaciones abiertas. Elige SUBE o BAJA para empezar.'
                    : 'Nenhuma ordem em andamento. Abra uma posição ACIMA ou ABAIXO para acompanhar ao vivo aqui.'}
                </div>
              ) : (
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '12px', textAlign: 'left' }}>
                  <thead>
                    <tr style={{ color: '#8A92A1', borderBottom: isBinmax ? '1px solid rgba(244, 245, 247, 0.08)' : '1px solid #1a273e' }}>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Activo' : 'ID / Ativo'}</th>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Dirección' : 'Direção'}</th>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Inversión' : 'Valor'}</th>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Tiempo restante' : 'Expiração'}</th>
                      <th style={{ padding: '8px 6px' }}>{isBinmax ? 'Estado' : 'Status'}</th>
