              lineHeight: 1,
            }}
            title="Cerrar (ESC)"
          >
            ✕
          </button>
        </div>

        {/* Barra de Pesquisa e Categorias */}
        <div style={{ padding: '16px 20px', display: 'flex', flexDirection: 'column', gap: '12px', background: '#11151D' }}>
          {/* Campo de Busca */}
