      <div style={{ display: "flex", gap: "12px", marginTop: "8px" }}>
        <button
          disabled={isLocked || isSubmitting}
          onClick={() => handleSubmitOrder("UP")}
          style={{
            flex: 1,
            background: isLocked ? "#333A48" : "#089981",
            color: "#FFFFFF",
            border: "none",
            borderRadius: "6px",
            padding: "14px",
            fontSize: "15px",
            fontWeight: "bold",
