import React, { createContext, useContext, useState, useEffect } from "react";
import ptBR from "./locales/pt-BR.json";
import esES from "./locales/es-ES.json";
import {
  DisplayCurrencyCode,
  convertUSDMinorToDisplay,
  CURRENCY_CONFIGS
} from "@broker/shared";

export type Locale = "pt-BR" | "es-ES";
export type ActiveDisplayCurrency = DisplayCurrencyCode | "USD";

const translations: Record<Locale, any> = {
  "pt-BR": ptBR,
  "es-ES": esES
};

interface I18nContextType {
  locale: Locale;
  setLocale: (loc: Locale) => void;
  currency: ActiveDisplayCurrency;
  setCurrency: (curr: ActiveDisplayCurrency) => void;
  t: (path: string) => string;
  formatBalance: (minorUSD: number | null) => string;
}

const I18nContext = createContext<I18nContextType | null>(null);

export const I18nProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [locale, setLocaleState] = useState<Locale>(() => {
    const saved = localStorage.getItem("broker_locale");
    if (saved === "pt-BR" || saved === "es-ES") return saved;
    // Detecção baseada no navegador
    return navigator.language.startsWith("pt") ? "pt-BR" : "es-ES";
  });

  const [currency, setCurrencyState] = useState<ActiveDisplayCurrency>(() => {
    const saved = localStorage.getItem("broker_currency");
    if (saved && (saved === "USD" || CURRENCY_CONFIGS[saved as DisplayCurrencyCode])) {
      return saved as ActiveDisplayCurrency;
    }
    return "USD";
  });

  const setLocale = (loc: Locale) => {
    setLocaleState(loc);
    localStorage.setItem("broker_locale", loc);
  };

  const setCurrency = (curr: ActiveDisplayCurrency) => {
    setCurrencyState(curr);
    localStorage.setItem("broker_currency", curr);
  };

  const t = (path: string): string => {
    const keys = path.split(".");
    let current = translations[locale];
    for (const k of keys) {
      if (current && typeof current === "object" && k in current) {
        current = current[k];
      } else {
        // Fallback para pt-BR
        let fallback = translations["pt-BR"];
        for (const fk of keys) {
          if (fallback && typeof fallback === "object" && fk in fallback) {
            fallback = fallback[fk];
          } else {
            return path;
          }
        }
        return typeof fallback === "string" ? fallback : path;
      }
    }
    return typeof current === "string" ? current : path;
  };

  const formatBalance = (minorUSD: number | null): string => {
    if (minorUSD === null || minorUSD === undefined) return "--";

    if (currency === "USD") {
      const usdAmount = minorUSD / 100;
      return `$ ${usdAmount.toLocaleString(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }

    // Taxas nominais padrão para conversão rápida de UI
    const defaultRates: Record<DisplayCurrencyCode, number> = {
      BRL: 5.50,
      MXN: 19.50,
      COP: 4150.00,
      ARS: 980.00,
      CLP: 940.00,
      PEN: 3.75
    };

    const rate = defaultRates[currency as DisplayCurrencyCode] || 1.0;
    const converted = convertUSDMinorToDisplay(minorUSD, rate, currency as DisplayCurrencyCode, locale);
    return converted.formatted;
  };

  return (
    <I18nContext.Provider value={{ locale, setLocale, currency, setCurrency, t, formatBalance }}>
      {children}
    </I18nContext.Provider>
  );
};

export function useTranslation() {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error("useTranslation deve ser utilizado dentro de um I18nProvider");
  }
  return context;
}

/**
 * Feature Flags da Plataforma Binmax
 * Governa a ativação da nova sala de operações (NEW_TRADEROOM)
 * de forma isolada, resiliente e com fallback seguro.
 */

export const FEATURE_FLAGS = {
  NEW_TRADEROOM: 'NEW_TRADEROOM',
} as const;

let memoryFlag: boolean | null = null;

export function isNewTraderoomEnabled(): boolean {
  if (memoryFlag !== null) return memoryFlag;

  try {
    const storage = typeof localStorage !== 'undefined' ? localStorage : (globalThis as any).localStorage;
    const win = typeof window !== 'undefined' ? window : (globalThis as any).window;

    if (win?.location?.search) {
      const params = new URLSearchParams(win.location.search);
      const themeParam = params.get('theme');
      const uiParam = params.get('ui');
      const flagParam = params.get('new_traderoom');

      if (themeParam === 'binmax' || uiParam === 'binmax' || flagParam === '1' || flagParam === 'true') {
        return true;
      }
      if (themeParam === 'legacy' || uiParam === 'legacy' || flagParam === '0' || flagParam === 'false') {
        return false;
      }
    }

    if (storage) {
      const stored = storage.getItem('NEW_TRADEROOM');
      if (stored === 'true') return true;
      if (stored === 'false') return false;
    }

    // Variável de ambiente Vite (opcional)
    const envFlag = (import.meta as any)?.env?.VITE_NEW_TRADEROOM;
    if (envFlag === 'true') return true;
    if (envFlag === 'false') return false;
  } catch {
    // Falha silenciosa em ambientes restritos, preservando estabilidade
  }

  // Padrão ativado para garantir o novo layout Turbo Prata
  return true;
}

export function setNewTraderoomEnabled(enabled: boolean): void {
  memoryFlag = enabled;
  try {
    const storage = typeof localStorage !== 'undefined' ? localStorage : (globalThis as any).localStorage;
    if (storage) {
      storage.setItem('NEW_TRADEROOM', enabled ? 'true' : 'false');
    }
  } catch {
    // ignore
  }
}

export const setFeatureFlagForTesting = setNewTraderoomEnabled;

import { describe, it, expect } from 'vitest';
import { FALLBACK_MARKET_NEWS, type MarketNewsArticle } from './news-types';

describe('[PLANO 3 - GATE 3] Notícias de Mercado & Sentimento', () => {
  it('carrega lista estruturada de notícias com sentimento e categorias válidas', () => {
    expect(FALLBACK_MARKET_NEWS.length).toBeGreaterThanOrEqual(4);
    for (const item of FALLBACK_MARKET_NEWS) {
      expect(item.id).toBeDefined();
      expect(item.title.length).toBeGreaterThan(10);
      expect(item.summary.length).toBeGreaterThan(15);
      expect(['BULLISH', 'BEARISH', 'NEUTRAL']).toContain(item.sentiment);
      expect(['ALL', 'FOREX', 'CRYPTO', 'INDICES', 'GLOBAL']).toContain(item.category);
      expect(Number.isFinite(Date.parse(item.published_at))).toBe(true);
    }
  });

  it('filtra notícias por categoria corretamente', () => {
    const cryptoNews = FALLBACK_MARKET_NEWS.filter((n) => n.category === 'CRYPTO');
    expect(cryptoNews.length).toBeGreaterThan(0);
    for (const item of cryptoNews) {
      expect(item.category).toBe('CRYPTO');
    }

    const indicesNews = FALLBACK_MARKET_NEWS.filter((n) => n.category === 'INDICES');
    expect(indicesNews.length).toBeGreaterThan(0);
    for (const item of indicesNews) {
      expect(item.category).toBe('INDICES');
    }
  });

  it('filtra notícias por busca textual de palavra-chave', () => {
    const query = 'Bitcoin'.toLowerCase();
    const matches = FALLBACK_MARKET_NEWS.filter(
      (n) =>
        n.title.toLowerCase().includes(query) ||
        n.summary.toLowerCase().includes(query)
    );

    expect(matches.length).toBeGreaterThan(0);
    expect(matches[0].title).toContain('Bitcoin');
  });

  it('[Segurança Anti-XSS] sanitiza strings maliciosas com escape HTML rigoroso', () => {
    function escapeHtml(str: string): string {
      return str
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }

    const maliciousTitle = `<script>alert('XSS')</script><img src=x onerror=stealToken()>`;
    const sanitized = escapeHtml(maliciousTitle);

    expect(sanitized).not.toContain('<script>');
    expect(sanitized).not.toContain('<img');
    expect(sanitized).toContain('&lt;script&gt;');
    expect(sanitized).toContain('&lt;img');
  });
});

import { useEffect, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ApiError, getContract, openContract, type Receipt } from '../api/client';
import { formatMinor, formatCurrencyBinmax, parseStakeInput } from '../lib/money';
import { soundEngine } from '../lib/sound-engine';
import { getAssetMeta } from '../catalog/assets';
import { safeRandomUUID } from '../lib/uuid';
import { ExpiryDropdown } from './ExpiryDropdown';
import { calculateExecutionExpiry, calculateExpirySlots, formatSecondsToMmSs, type ExpirySlot, type ExpiryMode } from './expiry-calculator';
import { isNewTraderoomEnabled } from '../lib/feature-flags';

const messages: Record<string, string> = {
  INDEX_PAUSED: 'Índice pausado pela operação.',
  INSUFFICIENT_BALANCE: 'Saldo insuficiente.',
  WALLET_PROVISIONING: 'A carteira está sendo preparada. Tente novamente em instantes.',
  RATE_LIMITED: 'Muitas ordens em sequência. Aguarde alguns segundos.',
  TICK_UNAVAILABLE: 'Cotação indisponível no momento.',
  AUTH_REQUIRED: 'Sua sessão expirou. Entre novamente.',
  FEED_STALE: 'Feed de cotações desatualizado. Ordem bloqueada por segurança.',
  KILLSWITCH_ACTIVE: 'Kill switch de risco ativo. Operação suspensa temporariamente para este ativo.',
};

export interface OrderTicketProps {
  symbol: string;
  paused: boolean;
  stale: boolean;
  availableMinor: number | null;
  soundEnabled?: boolean;
  onChanged: () => void;
}

export function OrderTicket({
  symbol,
  paused,
  stale,
  availableMinor,
  soundEnabled = true,
  onChanged,
}: OrderTicketProps) {
  const isBinmax = isNewTraderoomEnabled();
  const [stake, setStake] = useState(isBinmax ? '100' : '10,00');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [receipt, setReceipt] = useState<Receipt | null>(null);
  const [now, setNow] = useState(Date.now());
  const [selectedSlotId, setSelectedSlotId] = useState<string>('candle_1m');
  const [selectedSlot, setSelectedSlot] = useState<ExpirySlot | null>(null);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const intent = useRef<{ key: string; direction: 'UP' | 'DOWN'; stakeMinor: number } | null>(null);
  const notified = useRef<string | null>(null);
  const executingRef = useRef(false);
  const slots = calculateExpirySlots(new Date(), -3);
  const activeSlot = slots.find((s) => s.id === selectedSlotId) ?? slots[0];

  const navigateSlot = (direction: 1 | -1) => {
    soundEngine.playClick();
    const currentIndex = slots.findIndex((s) => s.id === selectedSlotId);
    const nextIndex = Math.max(0, Math.min(slots.length - 1, currentIndex + direction));
    const target = slots[nextIndex];
    if (target) {
      setSelectedSlotId(target.id);
      setSelectedSlot(target);
    }
  };

  const contract = useQuery({
    queryKey: ['contract', receipt?.id],
    queryFn: () => getContract(receipt!.id),
    enabled: Boolean(receipt?.id),
    refetchInterval: (query) =>
      ['SETTLED', 'FAILED_COMPENSATION', 'CANCELLED'].includes(query.state.data?.status ?? '')
        ? false
        : 1000,
  });

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 250);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    soundEngine.setMuted(!soundEnabled);
  }, [soundEnabled]);

  useEffect(() => {
    const value = contract.data;
    if (value && ['SETTLED', 'FAILED_COMPENSATION', 'CANCELLED'].includes(value.status) && notified.current !== value.id) {
      notified.current = value.id;
      if (value.result === 'WIN') soundEngine.playWin();
      else if (value.result === 'LOSS') soundEngine.playLoss();
      else if (value.result === 'DRAW') soundEngine.playDraw();
      onChanged();
    }
  }, [contract.data, onChanged]);

  const stakeMinor = parseStakeInput(stake);

  // Contagem regressiva da vela atual (ciclo de 60 segundos)
  const secondsInMinute = Math.floor(now / 1000) % 60;
  const candleRemaining = 60 - secondsInMinute;
  const isLocked30s = false;

  const remainingReceipt = receipt
    ? Math.max(0, Math.ceil((Date.parse(receipt.expires_at) - now) / 1000))
    : 0;

  const currentAvailable = availableMinor ?? 1000000;
  const blocked =
    paused ||
    stale ||
    stakeMinor === null ||
    stakeMinor > currentAvailable;

  const assetMeta = getAssetMeta(symbol);
  const payoutPct = assetMeta.payout;
  const payoutProfitMinor = stakeMinor !== null ? Math.round(stakeMinor * (payoutPct / 100)) : 850;
  const totalReturnMinor = (stakeMinor ?? 1000) + payoutProfitMinor;

  const adjustStake = (delta: number) => {
    soundEngine.playClick();
    const current = stakeMinor !== null ? stakeMinor : 1000;
    const next = Math.max(100, Math.min(10000, current + delta));
    if (next % 100 === 0) {
      setStake(String(next / 100));
    } else {
      setStake((next / 100).toFixed(2).replace('.', ','));
    }
  };

  const setPreset = (valueUsd: number) => {
    soundEngine.playClick();
    setStake(valueUsd.toFixed(2).replace('.', ','));
  };

  async function handleExecute(direction: 'UP' | 'DOWN') {
    if (executingRef.current || blocked || busy || stakeMinor === null) return;
    executingRef.current = true;
    setBusy(true);
    setError('');
    soundEngine.playOrderOpen();

    try {
      const key = safeRandomUUID();
      const current = { key, direction, stakeMinor };
      intent.current = current;
      const mode: ExpiryMode = selectedSlot?.mode ?? '1M_FIXED';
      const { durationMs, targetEpochMs } = calculateExecutionExpiry(mode, Date.now());
      const durationSeconds = Math.max(30, Math.round(durationMs / 1000));
      const targetExpiresAt = new Date(targetEpochMs).toISOString();

      const opened = await openContract(
        symbol,
        current.direction,
        current.stakeMinor,
        current.key,
        durationSeconds,
        targetExpiresAt,
        mode
      );
      setReceipt(opened);
      intent.current = null;
      onChanged();
    } catch (cause) {
      if (cause instanceof ApiError) {
        setError(messages[cause.code] ?? 'Não foi possível enviar a ordem.');
        if (cause.status < 500 && cause.status !== 429) intent.current = null;
        if (cause.code === 'INDEX_PAUSED') onChanged();
      } else {
        setError(cause instanceof Error ? cause.message : 'Falha ao processar ordem. Tente novamente.');
      }
    } finally {
      executingRef.current = false;
      setBusy(false);
    }
  }

  // Atalhos de teclado seguros com supressão sob feed stale ou bloqueio (Passo 5.5)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) return;
      if (blocked || busy || stakeMinor === null) return;

      if (e.key === 'ArrowUp' || e.key.toLowerCase() === 'u') {
        e.preventDefault();
        handleExecute('UP');
      } else if (e.key === 'ArrowDown' || e.key.toLowerCase() === 'd') {
        e.preventDefault();
        handleExecute('DOWN');
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [blocked, busy, stakeMinor]);

  if (isBinmax) {
    const formattedExpiryDisplay = activeSlot
      ? formatSecondsToMmSs(activeSlot.remainingSeconds)
      : '00:21';

    return (
      <div
        className="order-dock-container binmax-order-dock"
        data-testid="binmax-order-ticket"
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '8px',
          width: '100%',
          color: '#F4F5F7',
          boxSizing: 'border-box',
        }}
      >
        {/* D1: MONTO */}
        <div className="binmax-ticket-block" data-testid="ticket-block-monto">
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              marginBottom: '4px',
            }}
          >
            <span style={{ fontSize: '11px', color: '#8A92A1', fontWeight: 500 }}>
              Monto
            </span>
            <span
              aria-label="Ayuda monto"
              style={{
                fontSize: '9px',
                color: '#8A92A1',
                cursor: 'pointer',
                width: '13px',
                height: '13px',
                borderRadius: '50%',
                border: '1px solid rgba(138, 146, 161, 0.4)',
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                lineHeight: 1,
              }}
            >
              ?
            </span>
          </div>

          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              background: '#151922',
              border: '1px solid rgba(244, 245, 247, 0.08)',
              borderRadius: '6px',
              height: '34px',
              boxSizing: 'border-box',
              overflow: 'hidden',
            }}
          >
            <button
              type="button"
              aria-label="Disminuir monto"
              onClick={() => adjustStake(-100)}
              style={{
                width: '28px',
                height: '100%',
                background: 'rgba(255, 255, 255, 0.03)',
                border: 'none',
                borderRight: '1px solid rgba(244, 245, 247, 0.06)',
                color: '#8A92A1',
                fontSize: '15px',
