            border: 'none',
            color: '#ffffff',
            cursor: blocked || busy ? 'not-allowed' : 'pointer',
            opacity: blocked || busy ? 0.45 : 1,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            padding: '0 20px',
            boxShadow: blocked || busy ? 'none' : '0 4px 20px rgba(255, 61, 113, 0.35)',
