import { FastifyPluginAsync } from "fastify";

interface HistoryQuery {
  symbol?: string;
  resolution?: string;
  from?: string;
  to?: string;
  countback?: string;
}

interface SymbolsQuery {
  symbol?: string;
}

export const chartRoutes: FastifyPluginAsync = async (server) => {
  // 1. GET /api/v1/chart/config (TradingView UDF Config)
  server.get("/api/v1/chart/config", async () => {
    return {
      supported_resolutions: ["1S", "1", "5", "15", "60"],
      supports_group_request: false,
      supports_marks: false,
      supports_search: false,
      supports_time: true,
      supports_timescale_marks: false
    };
  });

  // 2. GET /api/v1/chart/time (UTC Server Time in seconds)
  server.get("/api/v1/chart/time", async () => {
    return Math.floor(Date.now() / 1000);
  });

  // 3. GET /api/v1/chart/symbols (Symbol Metadata)
  server.get<{ Querystring: SymbolsQuery }>("/api/v1/chart/symbols", async (request, reply) => {
    const symbol = request.query.symbol || "SYNTH_VOL_50";

    // Busca no banco se existe
    let name = symbol;
    let description = "Synthetic Volatility Index (OTC)";
    let pricescale = 100000;

    try {
      const res = await server.pg.query("SELECT symbol, name FROM indices WHERE symbol = $1", [symbol]);
      if (res.rows.length > 0) {
        name = res.rows[0].symbol;
        description = res.rows[0].name;
      }
    } catch {
      // Fallback gracioso caso tabela não esteja populada ainda
    }

    return {
      name,
      ticker: name,
      description,
      type: "synthetic",
      session: "24x7",
      exchange: "BROKER",
      listed_exchange: "BROKER",
      timezone: "Etc/UTC",
      minmov: 1,
      pricescale,
      has_intraday: true,
      has_seconds: true,
      has_no_volume: false,
      supported_resolutions: ["1S", "1", "5", "15", "60"]
    };
  });

  // 4. GET /api/v1/chart/history (TradingView Bars)
  server.get<{ Querystring: HistoryQuery }>("/api/v1/chart/history", async (request, reply) => {
    const { symbol = "SYNTH_VOL_50", resolution = "1", from, to, countback } = request.query;

    if (!from || !to) {
      return reply.status(400).send({ s: "error", errmsg: "Missing 'from' or 'to' parameters" });
    }

    const fromSec = parseInt(from, 10);
    const toSec = parseInt(to, 10);
    const fromDate = new Date(fromSec * 1000);
    const toDate = new Date(toSec * 1000);

    // Mapeia resolução UDF para intervalo do banco
    let dbInterval = "1m";
    if (resolution === "1S" || resolution === "1s") {
      dbInterval = "1s";
    } else if (resolution === "5" || resolution === "15" || resolution === "60") {
      dbInterval = "5m";
    }

    const limit = countback ? Math.min(parseInt(countback, 10), 1000) : 500;

    try {
      const query = `
        SELECT bucket_start, open, high, low, close, volume
        FROM candles
        WHERE symbol = $1
          AND interval = $2
          AND bucket_start >= $3
          AND bucket_start <= $4
        ORDER BY bucket_start ASC
        LIMIT $5;
      `;

      const result = await server.pg.query(query, [symbol, dbInterval, fromDate, toDate, limit]);

      if (result.rows.length === 0) {
        return { s: "no_data" };
      }

      const t: number[] = [];
      const o: number[] = [];
      const h: number[] = [];
      const l: number[] = [];
      const c: number[] = [];
      const v: number[] = [];

      for (const row of result.rows) {
        t.push(Math.floor(new Date(row.bucket_start).getTime() / 1000));
        o.push(parseFloat(row.open));
        h.push(parseFloat(row.high));
        l.push(parseFloat(row.low));
        c.push(parseFloat(row.close));
        v.push(parseInt(row.volume, 10));
      }

      return {
        s: "ok",
        t,
        o,
        h,
        l,
        c,
        v
      };
    } catch (err: any) {
      server.log.error(err, "Error fetching chart history");
      return reply.status(500).send({ s: "error", errmsg: "Internal server error" });
    }
  });

  // 5. GET /api/v1/snapshot (Atomic Snapshot for Clean Rebuild on Gap - Subetapa 4)
  server.get<{ Querystring: { symbol?: string } }>("/api/v1/snapshot", async (request, reply) => {
    const symbol = request.query.symbol;
    if (!symbol) {
      return reply.status(400).send({ error: "Missing 'symbol' parameter" });
    }

    try {
      const res = await server.pg.query(
        `SELECT s.symbol, s.last_sequence, s.last_price, s.updated_at as last_ts, s.last_hash, i.status
         FROM index_state s
         JOIN indices i ON s.symbol = i.symbol
         WHERE s.symbol = $1`,
        [symbol]
      );

      if (res.rows.length === 0) {
        return reply.status(404).send({ error: "Symbol not found in index_state" });
      }

      const row = res.rows[0];
      const eventTime = new Date(row.last_ts).getTime();
      const arrivalTime = Date.now();
      return {
        symbol: row.symbol,
        sequence: Number(row.last_sequence),
        price: row.last_price,
        ts: new Date(row.last_ts).toISOString(),
        event_time: eventTime,
        arrival_time: arrivalTime,
        latency_ms: Math.max(0, arrivalTime - eventTime),
        hash: row.last_hash,
        status: row.status
      };
    } catch (err: any) {
      server.log.error(err, "Error fetching symbol snapshot");
      return reply.status(500).send({ error: "Internal server error" });
    }
  });

  // 6. GET /api/candles & GET /candles (Public Historical Candles with before & limit pagination - Subetapa 5)
  interface CandlesQuery {
    symbol?: string;
    interval?: string;
    limit?: string;
    before?: string;
  }

  const handleCandlesRequest = async (request: any, reply: any) => {
    const symbol = request.query.symbol || "SYNTH_VOL_50";
    const interval = request.query.interval || "1m";
    const rawLimit = parseInt(request.query.limit || "1440", 10);
    const limit = Math.min(Math.max(1, isNaN(rawLimit) ? 1440 : rawLimit), 10080);
    const beforeSec = request.query.before ? parseInt(request.query.before, 10) : null;

    try {
      let query = `
        SELECT bucket_start, open, high, low, close, volume
        FROM candles
        WHERE symbol = $1 AND interval = $2
      `;
      const params: any[] = [symbol, interval];

      if (beforeSec && !isNaN(beforeSec) && beforeSec > 0) {
        query += ` AND bucket_start < $3 ORDER BY bucket_start DESC LIMIT $4;`;
        params.push(new Date(beforeSec * 1000), limit);
      } else {
        query += ` ORDER BY bucket_start DESC LIMIT $3;`;
        params.push(limit);
      }

      const res = await server.pg.query(query, params);
      const rows = res.rows.reverse(); // Ordem cronológica ASC

      const data = rows.map((r: any) => ({
        time: Math.floor(new Date(r.bucket_start).getTime() / 1000),
        open: r.open,
        high: r.high,
        low: r.low,
        close: r.close,
        volume: parseInt(r.volume, 10) || 1,
      }));

      reply.header("X-Total-Bars", String(data.length));
      reply.header("X-Has-More", String(data.length >= limit));
      reply.header("Cache-Control", "public, max-age=5");

      return data;
    } catch (err: any) {
      server.log.error(err, "Error fetching candles from database");
      return reply.status(500).send({ error: "Internal server error" });
    }
  };

  server.get<{ Querystring: CandlesQuery }>("/api/candles", handleCandlesRequest);
  server.get<{ Querystring: CandlesQuery }>("/candles", handleCandlesRequest);
};

import { FastifyPluginAsync } from "fastify";
import { OpenContractSchema } from "@broker/shared";
import { ContractService } from "../services/contract-service.js";

export const contractRoutes: FastifyPluginAsync = async (server) => {
  const contractService = new ContractService(server.pg, server.redis);

  // POST /api/v1/contracts (Abertura de contrato UP/DOWN)
  const preHandlers = [(server as any).authenticate];
  if (typeof (server as any).enforceTradingEnabled === 'function') {
    preHandlers.push((server as any).enforceTradingEnabled);
  }

  server.post(
    "/api/v1/contracts",
    {
      preHandler: preHandlers
    },
    async (request, reply) => {
      const user = request.user;
      if (!user) {
        return reply.status(401).send({ error: "UNAUTHORIZED", message: "User not authenticated" });
      }

      const idempotencyKey = request.headers["idempotency-key"] as string;
      if (!idempotencyKey) {
        return reply.status(400).send({
          error: "BAD_REQUEST",
          message: "Header 'Idempotency-Key' is required (D-12, B-05)"
        });
      }

      // Validação estrita com Zod (rejeita qualquer campo extra)
      const parseResult = OpenContractSchema.safeParse(request.body);
      if (!parseResult.success) {
        return reply.status(400).send({
          error: "VALIDATION_ERROR",
          details: parseResult.error.format()
        });
      }

      try {
        const { contract, isDuplicate } = await contractService.openContract(
          user.id,
          idempotencyKey,
          parseResult.data
        );

        const statusCode = isDuplicate ? 200 : 201;
        return reply.status(statusCode).send({
          success: true,
          is_duplicate: isDuplicate,
          contract
        });
      } catch (err: any) {
        if (err.message?.includes("KILLSWITCH_ACTIVE")) {
          return reply.status(503).send({
            error: "KILLSWITCH_ACTIVE",
            message: "Kill switch ativo: feed de cotações instável ou desatualizado. Abertura bloqueada."
          });
        }
        if (err.message?.includes("FEED_STALE")) {
          return reply.status(503).send({
            error: "FEED_STALE",
            message: "Cotação desatualizada. Abertura bloqueada por segurança."
          });
        }
        if (err.message?.includes("TICK_UNAVAILABLE")) {
          return reply.status(503).send({
            error: "TICK_UNAVAILABLE",
            message: "Cotação indisponível para o ativo solicitado."
          });
        }
        if (err.message?.includes("RISK_LIMIT_EXCEEDED")) {
          return reply.status(422).send({
            error: "RISK_LIMIT_EXCEEDED",
            message: "Max platform risk cap (3% of float) reached for this candle and direction"
          });
        }
        server.log.error(err, "Failed to open contract");
        return reply.status(500).send({ error: "INTERNAL_ERROR", message: "Failed to process contract order" });
      }
    }
  );

  // GET /api/v1/contracts (Histórico de ordens do usuário)
  server.get(
    "/api/v1/contracts",
    {
      preHandler: [(server as any).authenticate]
    },
    async (request, reply) => {
      const user = request.user;
      if (!user) {
        return reply.status(401).send({ error: "UNAUTHORIZED" });
      }

      const contracts = await contractService.listUserContracts(user.id);
      return { contracts };
    }
  );

  // GET /api/v1/contracts/:id (Detalhes de contrato com proteção BOLA/IDOR - S-04)
  server.get<{ Params: { id: string } }>(
    "/api/v1/contracts/:id",
    {
      preHandler: [(server as any).authenticate]
    },
    async (request, reply) => {
      const user = request.user;
      if (!user) {
        return reply.status(401).send({ error: "UNAUTHORIZED" });
      }

      const contract = await contractService.getContractById(user.id, request.params.id);
      if (!contract) {
        // Retorna 404 para evitar inferência de existência de recursos de outros usuários (S-04)
        return reply.status(404).send({ error: "NOT_FOUND", message: "Contract not found" });
      }

      return { contract };
    }
  );
};

import { FastifyPluginAsync } from "fastify";
import { z } from "zod";
import { DynamicComplianceService } from "../services/compliance-kyc.js";

const SubmitTier1BodySchema = z.object({
  document_type: z.string().min(2).max(32),
  document_number: z.string().min(4).max(64),
  nationality_country: z.string().length(2),
  issuer_country: z.string().length(2)
});

const PreDepositCheckBodySchema = z.object({
  amount_minor: z.number().int().positive()
});

export const kycRoutes: FastifyPluginAsync = async (server) => {
  const complianceService = new DynamicComplianceService(server.pg, server.redis);

  /**
   * Endpoint protegido: Consulta do perfil de compliance e tier do próprio usuário
   */
  server.get(
    "/api/v1/kyc/me",
    {
      preHandler: [server.authenticate]
    },
    async (request) => {
      const userId = (request.user as any).id;
      const country = request.regulatoryContext?.country || "BR";
      const profile = await complianceService.getProfile(userId, country);
      return { profile };
    }
  );

  /**
   * Endpoint protegido: Submissão de documento para upgrade para Tier 1 com Anti-Red Zone Exclusion
   */
  server.post(
    "/api/v1/kyc/submit-tier1",
    {
      preHandler: [server.authenticate]
    },
    async (request, reply) => {
      const userId = (request.user as any).id;
      const parsed = SubmitTier1BodySchema.safeParse(request.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "BAD_REQUEST",
          message: "Dados de documento inválidos",
          details: parsed.error.issues
        });
      }

      const result = await complianceService.submitTier1Document(userId, {
        documentType: parsed.data.document_type,
        documentNumber: parsed.data.document_number,
        nationalityCountry: parsed.data.nationality_country,
        issuerCountry: parsed.data.issuer_country
      });

      if (result.status === "REJECTED") {
        return reply.status(403).send({
          error: "KYC_REJECTED",
          message: result.reason,
          status: result.status,
          tier: result.tier
        });
      }

      return {
        success: true,
        status: result.status,
        tier: result.tier
      };
    }
  );

  /**
   * Endpoint protegido: Verificação de limites e elegibilidade pré-depósito
   */
  server.post(
    "/api/v1/kyc/pre-deposit-check",
    {
      preHandler: [server.authenticate]
    },
    async (request, reply) => {
      const userId = (request.user as any).id;
      const parsed = PreDepositCheckBodySchema.safeParse(request.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "BAD_REQUEST",
          message: "Valor de depósito inválido",
          details: parsed.error.issues
        });
      }

      const country = request.regulatoryContext?.country || "UNKNOWN";
      const check = await complianceService.evaluateDepositEligibility(
        userId,
        parsed.data.amount_minor,
        country
      );

      if (!check.allowed) {
        return reply.status(403).send({
          error: "DEPOSIT_NOT_ALLOWED",
          reason: check.reason,
          tier: check.tier,
          requested_minor: check.requestedMinor,
          limit_minor: check.limitMinor
        });
      }

      return {
        allowed: true,
        tier: check.tier,
        status: check.status,
        requested_minor: check.requestedMinor,
        cumulative_minor: check.cumulativeMinor,
        limit_minor: check.limitMinor
      };
    }
  );
};

import { FastifyPluginAsync } from "fastify";
import { z } from "zod";
import { MirrorDomainService } from "../services/mirror-domains.js";

const RotateDomainBodySchema = z.object({
  blocked_domain: z.string().min(3).max(255),
  target_country: z.string().length(2).optional()
});

const AddMirrorBodySchema = z.object({
  domain_name: z.string().min(3).max(255),
  target_country: z.string().length(2).nullable().optional(),
  priority: z.number().int().min(1).max(1000).default(100),
  status: z.enum(["ACTIVE", "STANDBY", "BLOCKED", "DEAD"]).default("STANDBY")
});

export const mirrorRoutes: FastifyPluginAsync = async (server) => {
  const mirrorService = new MirrorDomainService(server.pg, server.redis);

  /**
   * Endpoint público: Lista de espelhos disponíveis para o país da requisição
   */
  server.get("/api/v1/geo/mirrors", async (request) => {
    const country = request.regulatoryContext?.country || "UNKNOWN";
    const mirrors = await mirrorService.listMirrors(country !== "UNKNOWN" ? country : undefined);
    const active = await mirrorService.getActiveMirror(country !== "UNKNOWN" ? country : undefined);

    return {
      detected_country: country,
      active_mirror: active?.domain_name || null,
      available_mirrors: mirrors.filter(m => m.status === "ACTIVE" || m.status === "STANDBY")
    };
  });

  /**
   * Endpoint administrativo: Listagem operacional de todos os domínios espelho
   */
  server.get(
    "/api/v1/admin/mirrors",
    {
      preHandler: [server.authenticate, server.requireRole("ADMIN")]
    },
    async (request) => {
      const countryQuery = (request.query as any)?.country;
      const mirrors = await mirrorService.listMirrors(countryQuery);
      return { mirrors };
    }
  );

  /**
   * Endpoint administrativo: Acionamento forçado de rotação de domínio por bloqueio
   */
  server.post(
    "/api/v1/admin/mirrors/rotate",
    {
      preHandler: [server.authenticate, server.requireRole("ADMIN")]
    },
    async (request, reply) => {
      const parsed = RotateDomainBodySchema.safeParse(request.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "BAD_REQUEST",
          message: "Payload inválido para rotação de domínio",
          details: parsed.error.issues
        });
      }

      try {
        const result = await mirrorService.rotateDomain(
          parsed.data.blocked_domain,
          parsed.data.target_country
        );

        return {
          success: true,
          action: "DOMAIN_ROTATED",
          previous_domain: result.previousDomain,
          new_active_domain: result.currentDomain,
          target_country: result.targetCountry,
          rotated_at: result.rotatedAt
        };
      } catch (err: any) {
        return reply.status(409).send({
          error: "ROTATION_FAILED",
          message: err.message || "Falha ao rotacionar domínio espelho"
        });
      }
    }
  );

  /**
   * Endpoint administrativo: Cadastro de novo domínio espelho na rede
   */
  server.post(
    "/api/v1/admin/mirrors",
    {
      preHandler: [server.authenticate, server.requireRole("ADMIN")]
    },
    async (request, reply) => {
      const parsed = AddMirrorBodySchema.safeParse(request.body);
      if (!parsed.success) {
        return reply.status(400).send({
          error: "BAD_REQUEST",
          message: "Payload inválido para cadastro de espelho",
          details: parsed.error.issues
        });
      }

      const created = await mirrorService.addMirror(parsed.data);
      return reply.status(201).send({
        success: true,
        mirror: created
      });
    }
  );
};

import { FastifyPluginAsync } from "fastify";
import { BlnkClient } from "@broker/wallet-adapter";

export const walletRoutes: FastifyPluginAsync = async (server) => {
  const blnkClient = new BlnkClient(process.env.BLNK_URL || "http://localhost:5001");

