        return reply.status(200).send({
          user_id: user.id,
          currency: "USD",
          available_minor: 1000000, // US$ 10.000,00 demo default
          reserved_minor: 0
        });
      }
    }
  );
};

/**
 * Backpressure Guard para WebSocket Gateway (Padrão de Resiliência contra Clientes Lentos)
 */

export interface BackpressureConfig {
  maxBufferedBytes?: number;     // Padrão: 64KB (65536 bytes)
  slowClientTimeoutMs?: number;  // Padrão: 5000ms (5 segundos)
}

export type SocketLike = {
  bufferedAmount: number;
  readyState: number;
  close(code?: number, reason?: string): void;
  on?(event: string, listener: (...args: any[]) => void): void;
};

export class BackpressureGuard {
  private readonly maxBufferedBytes: number;
  private readonly slowClientTimeoutMs: number;
  private saturatedSockets = new Map<SocketLike, number>();
  private pausedCount = 0;
  private disconnectedCount = 0;

  constructor(
    config: BackpressureConfig = {},
    private readonly timeFn: () => number = Date.now
  ) {
    this.maxBufferedBytes = config.maxBufferedBytes ?? 64 * 1024;
    this.slowClientTimeoutMs = config.slowClientTimeoutMs ?? 5000;
  }

  public shouldSend(socket: SocketLike): boolean {
    if (socket.readyState !== 1) return false;

    if (socket.bufferedAmount > this.maxBufferedBytes) {
      const now = this.timeFn();
      if (!this.saturatedSockets.has(socket)) {
        this.saturatedSockets.set(socket, now);
        this.pausedCount++;
      } else {
        const saturatedDuration = now - (this.saturatedSockets.get(socket) ?? now);
        if (saturatedDuration >= this.slowClientTimeoutMs) {
          this.disconnectSlowClient(socket);
          return false;
        }
      }
      return false;
    }

    if (this.saturatedSockets.has(socket)) {
      this.saturatedSockets.delete(socket);
      if (this.pausedCount > 0) this.pausedCount--;
    }

    return true;
  }

  public handleDrain(socket: SocketLike): void {
    if (this.saturatedSockets.has(socket)) {
      this.saturatedSockets.delete(socket);
      if (this.pausedCount > 0) this.pausedCount--;
    }
  }

  public checkAndPurgeSlowClients(): number {
    const now = this.timeFn();
    let purged = 0;
    for (const [socket, startTime] of this.saturatedSockets.entries()) {
      if (now - startTime >= this.slowClientTimeoutMs) {
        this.disconnectSlowClient(socket);
        purged++;
      }
    }
    return purged;
  }

  private disconnectSlowClient(socket: SocketLike): void {
    this.saturatedSockets.delete(socket);
    if (this.pausedCount > 0) this.pausedCount--;
    this.disconnectedCount++;
    try {
      socket.close(4429, 'Slow client backpressure timeout');
    } catch {
      // Ignora erro ao fechar
    }
  }

  public getPausedCount(): number {
    return this.pausedCount;
  }

  public getDisconnectedCount(): number {
    return this.disconnectedCount;
  }

  public getMaxBufferedBytes(): number {
    return this.maxBufferedBytes;
  }
}

import {
  CountryCode,
  KYCProfileDTO,
  KYCStatus,
  KYCTier,
  RED_ZONE_COUNTRIES
} from "@broker/shared";

export interface SubmitDocumentDTO {
  documentType: string;
  documentNumber: string;
  nationalityCountry: string;
  issuerCountry: string;
}

export interface DepositCheckResult {
  allowed: boolean;
  tier: KYCTier;
  status: KYCStatus;
  requestedMinor: number;
  cumulativeMinor: number;
  limitMinor: number;
  reason?: string;
}

export class DynamicComplianceService {
  constructor(
    private pg: any,
    private redis?: any
  ) {}

  /**
   * Obtém o perfil de KYC do usuário (ou inicializa perfil padrão Tier 0 se não existir)
   */
  async getProfile(userId: string, defaultCountry: string = "BR"): Promise<KYCProfileDTO> {
    const res = await this.pg.query(
      `SELECT id, user_id, country_code, document_type, document_number, status, tier, deposit_limit_minor, nationality_country_code, rejection_reason 
       FROM kyc_profiles 
       WHERE user_id = $1`,
      [userId]
    );

    if (res.rows.length > 0) {
      const row = res.rows[0];
      return {
        id: row.id,
        user_id: row.user_id,
        country_code: row.country_code,
        document_type: row.document_type,
        document_number: row.document_number,
        status: row.status as KYCStatus,
        tier: (row.tier || "TIER_0") as KYCTier,
        deposit_limit_minor: Number(row.deposit_limit_minor || 30000),
        nationality_country_code: row.nationality_country_code,
        rejection_reason: row.rejection_reason
      };
    }

    // Criar perfil padrão inicial em Tier 0
    const country = /^[A-Z]{2}$/.test(defaultCountry.toUpperCase()) ? defaultCountry.toUpperCase() : "BR";
    const insertRes = await this.pg.query(
      `INSERT INTO kyc_profiles (user_id, country_code, document_type, status, tier, deposit_limit_minor)
       VALUES ($1, $2, 'AUTO_TIER0', 'UNVERIFIED', 'TIER_0', 30000)
       RETURNING id, user_id, country_code, document_type, document_number, status, tier, deposit_limit_minor, nationality_country_code, rejection_reason`,
      [userId, country]
    );
    const row = insertRes.rows[0];
    return {
      id: row.id,
      user_id: row.user_id,
      country_code: row.country_code,
      document_type: row.document_type,
      document_number: row.document_number,
      status: row.status as KYCStatus,
      tier: row.tier as KYCTier,
      deposit_limit_minor: Number(row.deposit_limit_minor),
      nationality_country_code: row.nationality_country_code,
      rejection_reason: row.rejection_reason
    };
  }

  /**
   * Avalia elegibilidade pré-depósito sob regras de Tier e Zonas Regulatórias
   */
  async evaluateDepositEligibility(
    userId: string,
    requestedDepositMinor: number,
    accessCountry: string
  ): Promise<DepositCheckResult> {
    const countryUpper = accessCountry.toUpperCase();

    // 1. Bloqueio absoluto se o IP for de Zona Vermelha
    if ((RED_ZONE_COUNTRIES as readonly string[]).includes(countryUpper)) {
      return {
        allowed: false,
        tier: "TIER_0",
        status: "REJECTED",
        requestedMinor: requestedDepositMinor,
        cumulativeMinor: 0,
        limitMinor: 0,
        reason: "RED_ZONE_PROHIBITED: Financial transactions blocked from this jurisdiction."
      };
    }

    const profile = await this.getProfile(userId, countryUpper);

    // 2. Se o perfil foi rejeitado anteriormente (ex: tentou enviar passaporte US/EU)
    if (profile.status === "REJECTED") {
      return {
        allowed: false,
        tier: profile.tier,
        status: profile.status,
        requestedMinor: requestedDepositMinor,
        cumulativeMinor: 0,
        limitMinor: 0,
        reason: profile.rejection_reason || "ACCOUNT_REJECTED_BY_COMPLIANCE"
      };
    }

    // 3. Obter total cumulativo já depositado (via cache/jobs)
    const cumulativeKey = `user:deposit_cumulative:${userId}`;
    let cumulativeMinor = 0;
    if (this.redis) {
      try {
        const val = await this.redis.get(cumulativeKey);
        if (val) cumulativeMinor = parseInt(val, 10);
      } catch {
        cumulativeMinor = 0;
      }
    }

    const proposedTotal = cumulativeMinor + requestedDepositMinor;

    // 4. Se usuário está no Tier 0, aplica o teto estrito de $300 (30.000 centavos)
    if (profile.tier === "TIER_0" && proposedTotal > profile.deposit_limit_minor) {
      return {
        allowed: false,
        tier: profile.tier,
        status: profile.status,
        requestedMinor: requestedDepositMinor,
        cumulativeMinor,
        limitMinor: profile.deposit_limit_minor,
        reason: `TIER_0_LIMIT_EXCEEDED: Cumulative limit of $${profile.deposit_limit_minor / 100} exceeded. Submit Tier 1 ID document to increase deposit limit.`
      };
    }

    // 5. Se estiver em Tier 1 (Aprovado), valida contra o teto de Tier 1 ($10.000)
    if (profile.tier === "TIER_1" && proposedTotal > profile.deposit_limit_minor) {
      return {
        allowed: false,
        tier: profile.tier,
        status: profile.status,
        requestedMinor: requestedDepositMinor,
        cumulativeMinor,
        limitMinor: profile.deposit_limit_minor,
        reason: `TIER_1_LIMIT_EXCEEDED: Transaction exceeds maximum allowed tier limit.`
      };
    }

    return {
      allowed: true,
      tier: profile.tier,
      status: profile.status,
      requestedMinor: requestedDepositMinor,
      cumulativeMinor,
      limitMinor: profile.deposit_limit_minor
    };
  }

  /**
   * Submete e analisa documento de identidade para upgrade para Tier 1 com Anti-Red Zone Exclusion
   */
  async submitTier1Document(
    userId: string,
    data: SubmitDocumentDTO
  ): Promise<{ status: KYCStatus; tier: KYCTier; reason?: string }> {
    const nat = data.nationalityCountry.trim().toUpperCase();
    const issuer = data.issuerCountry.trim().toUpperCase();

    // REGRA INVIOLÁVEL: Anti-Red Zone Exclusion
    // Rejeição imediata se nacionalidade ou país emissor pertencer à Zona Vermelha
    const isRedNationality = (RED_ZONE_COUNTRIES as readonly string[]).includes(nat);
    const isRedIssuer = (RED_ZONE_COUNTRIES as readonly string[]).includes(issuer);

    if (isRedNationality || isRedIssuer) {
      const reason = `RED_ZONE_DOCUMENT_REJECTED: Citizens and residents of ${isRedNationality ? nat : issuer} are strictly prohibited from retail binary/synthetic contract trading.`;

      await this.pg.query(
        `UPDATE kyc_profiles 
         SET status = 'REJECTED', 
             nationality_country_code = $1, 
             rejection_reason = $2, 
             updated_at = NOW() 
         WHERE user_id = $3`,
        [nat, reason, userId]
      );

      return {
        status: "REJECTED",
        tier: "TIER_0",
        reason
      };
    }

    // Validação básica de completude do documento
    if (!data.documentNumber || data.documentNumber.trim().length < 4) {
      return {
        status: "UNVERIFIED",
        tier: "TIER_0",
        reason: "INVALID_DOCUMENT_NUMBER"
      };
    }

    // Aprovação de documento para jurisdições das Zonas Amarela e Verde
    // Elevação do teto para $10.000 (1.000.000 centavos)
    const TIER1_LIMIT_MINOR = 1000000;

    await this.pg.query(
      `UPDATE kyc_profiles 
       SET status = 'APPROVED', 
           tier = 'TIER_1', 
           deposit_limit_minor = $1, 
           document_type = $2, 
           document_number = $3, 
           nationality_country_code = $4, 
           rejection_reason = NULL, 
           updated_at = NOW() 
       WHERE user_id = $5`,
      [TIER1_LIMIT_MINOR, data.documentType, data.documentNumber, nat, userId]
    );

    return {
      status: "APPROVED",
      tier: "TIER_1"
    };
  }
}

import pg from "pg";
const { Pool } = pg;
type Pool = pg.Pool;
import { Redis } from "ioredis";
import { RiskManager } from "./risk-manager.js";
import { isMarketOpen } from "./trading-calendar.js";
import { OpenContractDTO } from "@broker/shared";

export interface ContractEntity {
  id: string;
  user_id: string;
  symbol: string;
  direction: "UP" | "DOWN";
  status: "OPEN" | "SETTLED" | "CANCELLED";
  stake_minor: number;
  payout_minor: number;
  entry_price: string;
  exit_price?: string;
  opened_at: Date;
  expires_at: Date;
  idempotency_key: string;
}

export class ContractService {
  private pool: Pool;
  private redis: Redis;
  private riskManager: RiskManager;

  constructor(pool: Pool, redis: Redis) {
    this.pool = pool;
    this.redis = redis;
    this.riskManager = new RiskManager(redis);
  }

  /**
   * Abre um contrato com checagem de idempotência, teto de risco e persistência ACID (B-01, B-05, I-03)
   */
  async openContract(
    userId: string,
    idempotencyKey: string,
    dto: OpenContractDTO
  ): Promise<{ contract: ContractEntity; isDuplicate: boolean }> {
    // 1. Verifica se já existe contrato com esta Idempotency-Key para o usuário
    const existingRes = await this.pool.query(
      `SELECT id, user_id, symbol, direction, status, stake_minor, payout_minor, entry_price, opened_at, expires_at, idempotency_key
       FROM contracts
       WHERE user_id = $1 AND idempotency_key = $2;`,
      [userId, idempotencyKey]
    );

    if (existingRes.rows.length > 0) {
      const row = existingRes.rows[0];
      return {
        contract: {
          id: row.id,
          user_id: row.user_id,
          symbol: row.symbol,
          direction: row.direction,
          status: row.status,
          stake_minor: parseInt(row.stake_minor, 10),
          payout_minor: parseInt(row.payout_minor, 10),
          entry_price: row.entry_price.toString(),
          opened_at: new Date(row.opened_at),
          expires_at: new Date(row.expires_at),
          idempotency_key: row.idempotency_key
        },
        isDuplicate: true
      };
    }

    // 2. Verificação imediata de Kill Switch no Redis (<1ms) - Subetapa 5
    if (await this.riskManager.isKillSwitchActive(dto.symbol)) {
      throw new Error(`KILLSWITCH_ACTIVE: Kill switch ativo para ${dto.symbol} por instabilidade no feed.`);
    }

    // 2.1. Validação de Sessão de Mercado (Perigo 7 / Técnica 4)
    if (!isMarketOpen(dto.symbol, new Date())) {
      throw new Error(`MARKET_CLOSED: Mercado fechado para o ativo ${dto.symbol} no momento da abertura.`);
    }

    // Obtém o último estado atômico gravado em index_state com validação estrita de staleness (M-02, B-01)
    const stateRes = await this.pool.query(
      `SELECT last_sequence, last_price, last_ts FROM index_state WHERE symbol = $1;`,
      [dto.symbol]
    );

    if (stateRes.rows.length === 0 || Number(stateRes.rows[0].last_sequence) <= 0) {
      throw new Error(`TICK_UNAVAILABLE: Nenhum tick oficial registrado para o ativo ${dto.symbol}`);
    }

    const lastTs = new Date(stateRes.rows[0].last_ts);
    const tickAgeMs = Date.now() - lastTs.getTime();
    const MAX_TICK_AGE_MS = 5000;

    if (tickAgeMs > MAX_TICK_AGE_MS) {
      // Dispara Kill Switch automático por 10s no Redis e emite auditoria estruturada
      await this.riskManager.activateKillSwitch(dto.symbol, "STALE_FEED", 10);
      console.warn(JSON.stringify({
        event: "KILL_SWITCH_TRIGGERED",
        symbol: dto.symbol,
        reason: "STALE_FEED",
        tick_age_ms: tickAgeMs,
        timestamp: new Date().toISOString()
      }));
      throw new Error(`KILLSWITCH_ACTIVE: Cotação para ${dto.symbol} desatualizada há ${tickAgeMs}ms (limite: ${MAX_TICK_AGE_MS}ms). Kill switch acionado.`);
    }

    const entryPrice = stateRes.rows[0].last_price.toString();
    const baseTime = lastTs;

    // Expiração em 60 segundos (D-10)
    const expiresAt = new Date(baseTime.getTime() + 60000);

    // 3. Validação do teto de risco de 3% no Redis
    const riskCheck = await this.riskManager.checkAndReserveRisk({
      symbol: dto.symbol,
      direction: dto.direction,
      expiryBucket: expiresAt,
      stakeMinor: dto.stake_minor
    });

    if (!riskCheck.approved) {
      if (riskCheck.reason === "KILLSWITCH_ACTIVE") {
        throw new Error(`KILLSWITCH_ACTIVE: Kill switch ativo para ${dto.symbol}`);
      }
      throw new Error(`RISK_LIMIT_EXCEEDED: ${riskCheck.reason}`);
    }

    // Payout fixo em 85% de lucro (total retorno = stake + 85% stake = 185% de stake)
    const payoutMinor = Math.floor(dto.stake_minor + (dto.stake_minor * 85) / 100);

    // 4. Inserção transacional no PostgreSQL (Contrato + Outbox RESERVE_STAKE)
    const client = await this.pool.connect();
    try {
      await client.query("BEGIN");

      const insertSql = `
        INSERT INTO contracts (
          user_id, symbol, direction, status, stake_minor, payout_minor, 
          entry_price, opened_at, expires_at, idempotency_key
        ) VALUES (
          $1, $2, $3, 'OPEN', $4, $5, $6, $7, $8, $9
        )
        RETURNING id, user_id, symbol, direction, status, stake_minor, payout_minor, entry_price, opened_at, expires_at, idempotency_key;
      `;

      const insertRes = await client.query(insertSql, [
        userId,
        dto.symbol,
        dto.direction,
        dto.stake_minor,
        payoutMinor,
        entryPrice,
        baseTime,
        expiresAt,
        idempotencyKey
      ]);

      const contractRow = insertRes.rows[0];

      // Inserção no Transactional Outbox para reserva de saldo no Blnk
      const outboxSql = `
        INSERT INTO outbox_events (event_type, payload, status)
        VALUES ('RESERVE_STAKE', $1, 'PENDING');
      `;

      const outboxPayload = JSON.stringify({
        contract_id: contractRow.id,
        user_id: userId,
        stake_minor: dto.stake_minor
      });

      await client.query(outboxSql, [outboxPayload]);

      await client.query("COMMIT");

      // 5. Adiciona ao Redis Sorted Set de pendências de expiração
      await this.redis.zadd("contracts:pending", expiresAt.getTime(), contractRow.id);

      const contract: ContractEntity = {
        id: contractRow.id,
        user_id: contractRow.user_id,
        symbol: contractRow.symbol,
        direction: contractRow.direction,
        status: contractRow.status,
        stake_minor: parseInt(contractRow.stake_minor, 10),
        payout_minor: parseInt(contractRow.payout_minor, 10),
        entry_price: contractRow.entry_price.toString(),
        opened_at: new Date(contractRow.opened_at),
        expires_at: new Date(contractRow.expires_at),
        idempotency_key: contractRow.idempotency_key
      };

      return { contract, isDuplicate: false };
    } catch (err) {
      await client.query("ROLLBACK");
      // Compensação: libera o risco que havia sido reservado no Redis
      await this.riskManager.releaseRisk({
        symbol: dto.symbol,
        direction: dto.direction,
        expiryBucket: expiresAt,
        stakeMinor: dto.stake_minor
      });
      throw err;
    } finally {
      client.release();
    }
  }

  /**
   * Consulta contratos do usuário autenticado (Prevenção BOLA/IDOR - S-04)
   */
  async listUserContracts(userId: string, limit: number = 50): Promise<ContractEntity[]> {
    const res = await this.pool.query(
      `SELECT id, user_id, symbol, direction, status, stake_minor, payout_minor, entry_price, exit_price, opened_at, expires_at, idempotency_key
       FROM contracts
       WHERE user_id = $1
       ORDER BY opened_at DESC
       LIMIT $2;`,
      [userId, limit]
    );

    return res.rows.map(row => ({
      id: row.id,
      user_id: row.user_id,
      symbol: row.symbol,
      direction: row.direction,
      status: row.status,
      stake_minor: parseInt(row.stake_minor, 10),
      payout_minor: parseInt(row.payout_minor, 10),
      entry_price: row.entry_price.toString(),
      exit_price: row.exit_price ? row.exit_price.toString() : undefined,
      opened_at: new Date(row.opened_at),
      expires_at: new Date(row.expires_at),
      idempotency_key: row.idempotency_key
    }));
  }

  /**
   * Consulta detalhes de um contrato com escopo de segurança obrigatório (S-04)
   */
  async getContractById(userId: string, contractId: string): Promise<ContractEntity | null> {
    const res = await this.pool.query(
      `SELECT id, user_id, symbol, direction, status, stake_minor, payout_minor, entry_price, exit_price, opened_at, expires_at, idempotency_key
       FROM contracts
       WHERE id = $1 AND user_id = $2;`,
      [contractId, userId]
    );

    if (res.rows.length === 0) return null;

    const row = res.rows[0];
    return {
      id: row.id,
      user_id: row.user_id,
      symbol: row.symbol,
      direction: row.direction,
      status: row.status,
      stake_minor: parseInt(row.stake_minor, 10),
      payout_minor: parseInt(row.payout_minor, 10),
      entry_price: row.entry_price.toString(),
      exit_price: row.exit_price ? row.exit_price.toString() : undefined,
      opened_at: new Date(row.opened_at),
      expires_at: new Date(row.expires_at),
      idempotency_key: row.idempotency_key
    };
  }
}

import { MirrorDomainDTO, MirrorDomainStatus } from "@broker/shared";

export interface RotateDomainResult {
  previousDomain: string;
  currentDomain: string;
  targetCountry: string | null;
  rotatedAt: string;
}

export class MirrorDomainService {
  constructor(
    private pg: any,
    private redis?: any
  ) {}

  /**
   * Lista todos os domínios espelhos cadastrados, opcionalmente filtrados por país
   */
  async listMirrors(targetCountry?: string): Promise<MirrorDomainDTO[]> {
    let query = `
      SELECT id, domain_name, target_country, status, priority, latency_ms, last_health_check_at 
      FROM mirror_domains
    `;
    const params: any[] = [];

    if (targetCountry) {
      query += ` WHERE target_country = $1 OR target_country IS NULL`;
      params.push(targetCountry.toUpperCase());
    }

    query += ` ORDER BY priority ASC, updated_at DESC`;

    const res = await this.pg.query(query, params);
    return res.rows.map((row: any) => ({
      id: row.id,
      domain_name: row.domain_name,
      target_country: row.target_country,
      status: row.status as MirrorDomainStatus,
      priority: row.priority,
      latency_ms: row.latency_ms,
      last_health_check_at: row.last_health_check_at?.toISOString?.() || row.last_health_check_at
    }));
  }

  /**
   * Obtém o domínio espelho atualmente ativo para um país (ou global)
   */
  async getActiveMirror(targetCountry?: string): Promise<MirrorDomainDTO | null> {
    const country = targetCountry ? targetCountry.toUpperCase() : null;

    // 1. Tentar busca específica para o país
    if (country) {
      const specificRes = await this.pg.query(
        `SELECT id, domain_name, target_country, status, priority, latency_ms, last_health_check_at 
         FROM mirror_domains 
         WHERE target_country = $1 AND status = 'ACTIVE' 
         ORDER BY priority ASC LIMIT 1`,
        [country]
      );
      if (specificRes.rows.length > 0) {
        const row = specificRes.rows[0];
        return {
          id: row.id,
          domain_name: row.domain_name,
          target_country: row.target_country,
          status: row.status,
          priority: row.priority,
          latency_ms: row.latency_ms,
          last_health_check_at: row.last_health_check_at?.toISOString?.() || row.last_health_check_at
        };
      }
    }

    // 2. Fallback para espelho global ativo
    const globalRes = await this.pg.query(
      `SELECT id, domain_name, target_country, status, priority, latency_ms, last_health_check_at 
       FROM mirror_domains 
       WHERE target_country IS NULL AND status = 'ACTIVE' 
       ORDER BY priority ASC LIMIT 1`
    );
    if (globalRes.rows.length > 0) {
      const row = globalRes.rows[0];
      return {
        id: row.id,
        domain_name: row.domain_name,
        target_country: row.target_country,
        status: row.status,
        priority: row.priority,
        latency_ms: row.latency_ms,
        last_health_check_at: row.last_health_check_at?.toISOString?.() || row.last_health_check_at
      };
    }

    return null;
  }

  /**
   * Executa rotação atômica de domínio após bloqueio DNS (ex: ordem judicial / Anatel)
   */
  async rotateDomain(blockedDomain: string, targetCountry?: string): Promise<RotateDomainResult> {
    const client = await this.pg.connect();
    try {
      await client.query("BEGIN");

      // 1. Marcar o domínio bloqueado como BLOCKED
      const updateBlocked = await client.query(
        `UPDATE mirror_domains 
         SET status = 'BLOCKED', updated_at = NOW() 
         WHERE domain_name = $1 
         RETURNING target_country`,
        [blockedDomain]
      );

      const country = targetCountry || (updateBlocked.rows[0]?.target_country ?? null);

      // 2. Selecionar o próximo domínio em STANDBY para o mesmo target_country
      let nextCandidateQuery = `
        SELECT id, domain_name 
        FROM mirror_domains 
        WHERE status = 'STANDBY' 
      `;
      const queryParams: any[] = [];

      if (country) {
        nextCandidateQuery += ` AND (target_country = $1 OR target_country IS NULL)`;
        queryParams.push(country);
      } else {
        nextCandidateQuery += ` AND target_country IS NULL`;
      }

      nextCandidateQuery += ` ORDER BY priority ASC LIMIT 1 FOR UPDATE`;

      const nextRes = await client.query(nextCandidateQuery, queryParams);

      if (nextRes.rows.length === 0) {
        throw new Error(`Nenhum domínio espelho STANDBY disponível para substituição de ${blockedDomain}`);
      }

      const nextDomain = nextRes.rows[0].domain_name;

      // 3. Promover o candidato a ACTIVE
      await client.query(
        `UPDATE mirror_domains 
         SET status = 'ACTIVE', updated_at = NOW() 
         WHERE domain_name = $1`,
        [nextDomain]
      );

      await client.query("COMMIT");

      // 4. Invalidação e Atualização no Redis
      if (this.redis) {
        try {
          if (country) {
            await this.redis.set(`reg:mirror:${country}`, nextDomain, "EX", 300);
          }
          await this.redis.del(`reg:mirror:GLOBAL`);

          // Notificar via Pub/Sub para outros nós de API e Gateways
          await this.redis.publish("system:domain_rotated", JSON.stringify({
            event: "DOMAIN_ROTATED",
            previousDomain: blockedDomain,
            currentDomain: nextDomain,
            targetCountry: country,
            rotatedAt: new Date().toISOString()
          }));
        } catch {
          // Ignora falha de cache / pubsub se Redis indisponível
        }
      }

      return {
        previousDomain: blockedDomain,
        currentDomain: nextDomain,
        targetCountry: country,
        rotatedAt: new Date().toISOString()
      };
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }
  }

  /**
   * Registra resultado de health-check e latência do domínio espelho
   */
  async registerHealthCheck(domainName: string, latencyMs: number, status?: MirrorDomainStatus): Promise<void> {
    let query = `
      UPDATE mirror_domains 
      SET latency_ms = $1, last_health_check_at = NOW(), updated_at = NOW()
    `;
    const params: any[] = [latencyMs, domainName];

    if (status) {
      query = `
        UPDATE mirror_domains 
        SET latency_ms = $1, status = $3, last_health_check_at = NOW(), updated_at = NOW()
        WHERE domain_name = $2
      `;
      params.push(status);
    } else {
      query += ` WHERE domain_name = $2`;
    }

    await this.pg.query(query, params);
  }

  /**
   * Cadastra novo domínio espelho na infraestrutura
   */
  async addMirror(data: {
    domain_name: string;
    target_country?: string | null;
    priority: number;
    status?: MirrorDomainStatus;
  }): Promise<MirrorDomainDTO> {
    const res = await this.pg.query(
      `INSERT INTO mirror_domains (domain_name, target_country, priority, status)
       VALUES ($1, $2, $3, $4)
       RETURNING id, domain_name, target_country, status, priority, latency_ms, last_health_check_at`,
      [
        data.domain_name,
        data.target_country || null,
        data.priority,
        data.status || "STANDBY"
      ]
    );
    const row = res.rows[0];
    return {
      id: row.id,
      domain_name: row.domain_name,
      target_country: row.target_country,
      status: row.status,
      priority: row.priority,
      latency_ms: row.latency_ms,
      last_health_check_at: row.last_health_check_at?.toISOString?.() || row.last_health_check_at
    };
  }
}

