export class RegulatoryZoneService {
  constructor(
    private pg?: any,
    private redis?: any
  ) {}

  /**
   * Sanitiza e extrai o código do país com proteção anti-spoofing
   */
  static extractCountry(req: FastifyRequest): string {
    const cfCountry = req.headers["cf-ipcountry"];
    if (typeof cfCountry === "string") {
      const sanitized = cfCountry.trim().toUpperCase();
      if (/^[A-Z]{2}$/.test(sanitized)) return sanitized;
      return "UNKNOWN";
    }

    const xCountry = req.headers["x-country-code"];
    if (typeof xCountry === "string") {
      const sanitized = xCountry.trim().toUpperCase();
      if (/^[A-Z]{2}$/.test(sanitized)) return sanitized;
      return "UNKNOWN";
    }

    const testCountry = req.headers["x-test-country"];
    if (process.env.NODE_ENV !== "production" && typeof testCountry === "string") {
      const sanitized = testCountry.trim().toUpperCase();
      if (/^[A-Z]{2}$/.test(sanitized)) return sanitized;
      return "UNKNOWN";
    }

    // Default para hospedagem direta e testes: Brasil 100% livre
    return "BR";
  }

  /**
   * Obtém informações da jurisdição por código de país
   */
  async getJurisdiction(countryCode: string): Promise<RegulatoryJurisdictionInfo> {
    const upper = countryCode.toUpperCase();

    // 1. Tentar Cache Redis
    if (this.redis) {
      try {
        const cached = await this.redis.get(`reg:jurisdiction:${upper}`);
        if (cached) return JSON.parse(cached);
      } catch {
        // Falha no Redis ignora e segue para Postgres/Static
      }
    }

    // 2. Tentar PostgreSQL se disponível
    if (this.pg) {
      try {
        const res = await this.pg.query(
          `SELECT country_code, country_name, zone, regulator_authority, enforcement_level, hard_block 
           FROM regulatory_jurisdictions WHERE country_code = $1`,
          [upper]
        );
        if (res.rows && res.rows.length > 0) {
          const row = res.rows[0];
          const info: RegulatoryJurisdictionInfo = {
            countryCode: row.country_code,
            countryName: row.country_name,
            zone: row.zone,
            regulatorAuthority: row.regulator_authority,
            enforcementLevel: row.enforcement_level,
            hardBlock: Boolean(row.hard_block)
          };

          if (this.redis) {
            try {
              await this.redis.set(`reg:jurisdiction:${upper}`, JSON.stringify(info), "EX", 3600);
            } catch {
              // Ignore cache write failure
            }
          }
          return info;
        }
      } catch {
        // Fallback para mapa estático
      }
    }

    // 3. Fallback estático em memória (Defesa em profundidade garantida)
    if (STATIC_REGULATORY_MAP[upper]) {
      return STATIC_REGULATORY_MAP[upper];
    }

    // Se não estiver em lista específica:
    // Se pertencer ao RED_ZONE_COUNTRIES:
    if (RED_ZONE_COUNTRIES.includes(upper as any)) {
      return {
        countryCode: upper,
        countryName: upper,
        zone: "RED",
        regulatorAuthority: "LOCAL_REGULATOR",
        enforcementLevel: "RETAIL_BAN",
        hardBlock: true
      };
    }

    // Caso padrão para países desconhecidos ou offshore não listados: GREEN de tolerância geral
    return {
      countryCode: upper,
      countryName: upper,
      zone: "GREEN",
      regulatorAuthority: "OFFSHORE_TOLERATED",
      enforcementLevel: "GENERAL_ACCESS",
      hardBlock: false
    };
  }

  /**
   * Determina se o país tem bloqueio rígido (Hard Geo-block)
   */
  async isHardBlocked(countryCode: string): Promise<boolean> {
    if (countryCode.toUpperCase() === "BR") return false; // Brasil 100% livre
    const info = await this.getJurisdiction(countryCode);
    return info.hardBlock || info.zone === "RED";
  }

  /**
   * Obtém o domínio espelho sugerido para o país
   */
  async getPreferredMirror(countryCode: string): Promise<string> {
    const upper = countryCode.toUpperCase();

    // 1. Tentar Cache Redis
    if (this.redis) {
      try {
        const cached = await this.redis.get(`reg:mirror:${upper}`);
        if (cached) return cached;
      } catch {
        // Fallback
      }
    }

    // 2. Consulta ao PostgreSQL
    if (this.pg) {
      try {
        // Busca espelho específico ativo
        const specificRes = await this.pg.query(
          `SELECT domain_name FROM mirror_domains 
           WHERE target_country = $1 AND status = 'ACTIVE' 
           ORDER BY priority ASC LIMIT 1`,
          [upper]
        );
        if (specificRes.rows && specificRes.rows.length > 0) {
          const domain = specificRes.rows[0].domain_name;
          if (this.redis) await this.redis.set(`reg:mirror:${upper}`, domain, "EX", 300).catch(() => {});
          return domain;
        }

        // Se não tiver espelho específico, busca espelho global ativo
        const globalRes = await this.pg.query(
          `SELECT domain_name FROM mirror_domains 
           WHERE target_country IS NULL AND status = 'ACTIVE' 
           ORDER BY priority ASC LIMIT 1`
        );
        if (globalRes.rows && globalRes.rows.length > 0) {
          const domain = globalRes.rows[0].domain_name;
          if (this.redis) await this.redis.set(`reg:mirror:${upper}`, domain, "EX", 300).catch(() => {});
          return domain;
        }
      } catch {
        // Fallback
      }
    }

    // 3. Fallback estático
    if (upper === "BR") return "app.nomedominio-br1.com";
    if (upper === "IN") return "app.nomedominio-in.com";
    return "app.nomedominio-global.com";
  }

  /**
   * Constrói o contexto regulatório completo da requisição
   */
  async resolveRoutingContext(req: FastifyRequest): Promise<RegulatoryRoutingContext> {
    const country = RegulatoryZoneService.extractCountry(req);
    const jurisdiction = await this.getJurisdiction(country);
    const suggestedMirror = await this.getPreferredMirror(country);

    return {
      country,
      zone: jurisdiction.zone,
      hardBlocked: jurisdiction.hardBlock,
      regulatorAuthority: jurisdiction.regulatorAuthority,
      suggestedMirror
    };
  }
}

import { Redis } from "ioredis";
import fs from "node:fs";
import path from "node:path";

export interface ReserveRiskParams {
  symbol: string;
  direction: "UP" | "DOWN";
  expiryBucket: Date;
  stakeMinor: number;
  payoutPercentage?: number;
}

export class RiskManager {
  private redis: Redis;
  private checkScript: string;
  private releaseScript: string;

  readonly DEFAULT_FLOAT_MINOR = 100_000_000; // US$ 1.000.000,00 inicial (100 traders demo)
  readonly PAYOUT_PERCENTAGE = 85;

  constructor(redis: Redis) {
    this.redis = redis;

    this.checkScript = `
      local deposit_float = tonumber(redis.call('GET', KEYS[1]) or '0')
      if deposit_float <= 0 then
        return {-1, 'ERR_NO_DEPOSIT_FLOAT'}
      end

      local max_risk_cap = math.floor(deposit_float * 0.03)
      local stake_minor = tonumber(ARGV[1])
      local payout_pct = tonumber(ARGV[2])
      local additional_risk = math.floor(stake_minor * payout_pct / 100)

      local current_exposure = tonumber(redis.call('GET', KEYS[2]) or '0')
      if (current_exposure + additional_risk) > max_risk_cap then
        return {-2, 'ERR_RISK_CAP_EXCEEDED'}
      end

      local new_exposure = redis.call('INCRBY', KEYS[2], additional_risk)
      redis.call('EXPIRE', KEYS[2], tonumber(ARGV[3]))

      return {1, 'APPROVED', new_exposure}
    `;

    this.releaseScript = `
      local current_exposure = tonumber(redis.call('GET', KEYS[1]) or '0')
      local amount_to_release = tonumber(ARGV[1])

      if current_exposure > 0 and amount_to_release > 0 then
        local to_decr = math.min(current_exposure, amount_to_release)
        redis.call('DECRBY', KEYS[1], to_decr)
      end

      return 1
    `;
  }

  async ensureDepositFloat(): Promise<void> {
    const floatKey = "broker:deposit_float_minor";
    const exists = await this.redis.exists(floatKey);
    if (!exists) {
      await this.redis.set(floatKey, this.DEFAULT_FLOAT_MINOR.toString());
    }
  }

  async activateKillSwitch(symbol: string, reason = "STALE_FEED", ttlSeconds = 10): Promise<void> {
    const key = `risk:killswitch:${symbol}`;
    await this.redis.set(key, reason, "EX", ttlSeconds);
  }

  async isKillSwitchActive(symbol: string): Promise<boolean> {
    const key = `risk:killswitch:${symbol}`;
    const val = await this.redis.get(key);
    return Boolean(val);
  }

  getRiskKey(symbol: string, expiryBucket: Date, direction: string): string {
    const bucketStartMs = Math.floor(expiryBucket.getTime() / 60000) * 60000;
    return `risk:candle:${symbol}:${bucketStartMs}:${direction}`;
  }

  async checkAndReserveRisk(params: ReserveRiskParams): Promise<{ approved: boolean; reason?: string }> {
    // 1. Verificação preliminar ultrarrápida de Kill Switch no Redis (<1ms) - Subetapa 5
    if (await this.isKillSwitchActive(params.symbol)) {
      return { approved: false, reason: "KILLSWITCH_ACTIVE" };
    }

    await this.ensureDepositFloat();

    const floatKey = "broker:deposit_float_minor";
    const riskKey = this.getRiskKey(params.symbol, params.expiryBucket, params.direction);
    const payoutPct = params.payoutPercentage || this.PAYOUT_PERCENTAGE;
    const ttlSeconds = 600;

    const result = (await this.redis.eval(
      this.checkScript,
      2,
      floatKey,
      riskKey,
      params.stakeMinor,
      payoutPct,
      ttlSeconds
    )) as [number, string, number?];

    const statusCode = result[0];
    if (statusCode === 1) {
      return { approved: true };
    }

    return {
      approved: false,
      reason: result[1] || "RISK_CAP_EXCEEDED"
    };
  }

  async releaseRisk(params: ReserveRiskParams): Promise<void> {
    const riskKey = this.getRiskKey(params.symbol, params.expiryBucket, params.direction);
    const payoutPct = params.payoutPercentage || this.PAYOUT_PERCENTAGE;
    const riskAmount = Math.floor((params.stakeMinor * payoutPct) / 100);

    await this.redis.eval(this.releaseScript, 1, riskKey, riskAmount);
  }
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import Fastify from "fastify";
import { chartRoutes } from "../src/routes/chart.js";

describe("Chart API UDF Endpoints", () => {
  async function buildTestApp(mockQueryResult: any = { rows: [] }) {
    const app = Fastify();
    // Decorate mock pg
    app.decorate("pg", {
      query: async (sql: string, params: any[]) => {
        if (typeof mockQueryResult === "function") {
          return mockQueryResult(sql, params);
        }
        return mockQueryResult;
      }
    } as any);

    await app.register(chartRoutes);
    return app;
  }

  it("GET /api/v1/chart/config returns valid UDF configurations", async () => {
    const app = await buildTestApp();
    const res = await app.inject({
      method: "GET",
      url: "/api/v1/chart/config"
    });

    assert.equal(res.statusCode, 200);
    const body = JSON.parse(res.payload);
    assert.deepEqual(body.supported_resolutions, ["1S", "1", "5", "15", "60"]);
    assert.equal(body.supports_time, true);
    await app.close();
  });

  it("GET /api/v1/chart/time returns current timestamp in seconds", async () => {
    const app = await buildTestApp();
    const beforeSec = Math.floor(Date.now() / 1000);
