      method: "GET",
      url: "/api/v1/chart/time"
    });
    const afterSec = Math.floor(Date.now() / 1000);

    assert.equal(res.statusCode, 200);
    const serverTime = parseInt(res.payload, 10);
    assert.ok(serverTime >= beforeSec && serverTime <= afterSec);
    await app.close();
