    assert.equal(res.statusCode, 404);
    const body = JSON.parse(res.payload);
    assert.equal(body.error, "NOT_FOUND");
    await app.close();
  });
});

import pg from "pg";
const { Pool } = pg;
type Pool = pg.Pool;
import { TimeframeAggregator, TIMEFRAMES, TickInput, CandleData } from "../aggregator/timeframe-aggregator.js";

const DATABASE_URL = process.env.DATABASE_URL || "postgresql://postgres:postgres@localhost:5432/broker";
const SYMBOL = process.env.SYMBOL || "SYNTH_VOL_50";
const BATCH_SIZE = 2000;

interface InMemoryBar {
  symbol: string;
  interval: string;
  bucket_start: Date;
  open: string;
  high: string;
  low: string;
  close: string;
  volume: number;
}

export async function rebuildCandlesForSymbol(pool: Pool, symbol: string): Promise<number> {
  console.log(`[RebuildCandles] Starting candle replay for symbol=${symbol}...`);

  let lastSequence = -1n;
  let totalProcessed = 0;
  let hasMore = true;

  // Mapa para acumular velas em memória durante o replay: `${interval}:${bucket_start_ms}` -> InMemoryBar
  const bars = new Map<string, InMemoryBar>();

  while (hasMore) {
    const query = `
      SELECT sequence, price, ts
      FROM ticks
      WHERE symbol = $1 AND sequence > $2
      ORDER BY sequence ASC
      LIMIT $3;
    `;
    const res = await pool.query(query, [symbol, lastSequence.toString(), BATCH_SIZE]);

    if (res.rows.length === 0) {
      hasMore = false;
      break;
    }

    for (const row of res.rows) {
      const seq = BigInt(row.sequence);
      const priceStr = row.price.toString();
      const priceNum = parseFloat(priceStr);
      const ts = new Date(row.ts);

      if (seq > lastSequence) {
        lastSequence = seq;
      }

      // Agrega para cada intervalo suportado (1m, 5m)
      for (const [interval, intervalMs] of Object.entries(TIMEFRAMES)) {
        const bucketStart = TimeframeAggregator.calculateBucketStart(ts, intervalMs);
        const key = `${interval}:${bucketStart.getTime()}`;

        const existing = bars.get(key);
        if (!existing) {
          bars.set(key, {
            symbol,
            interval,
            bucket_start: bucketStart,
            open: priceStr,
            high: priceStr,
            low: priceStr,
            close: priceStr,
            volume: 1
          });
        } else {
          const curHigh = parseFloat(existing.high);
          const curLow = parseFloat(existing.low);
          if (priceNum > curHigh) existing.high = priceStr;
          if (priceNum < curLow) existing.low = priceStr;
          existing.close = priceStr;
          existing.volume += 1;
        }
      }
      totalProcessed++;
    }

    console.log(`[RebuildCandles] Processed batch up to sequence ${lastSequence} (Total ticks: ${totalProcessed})`);
  }

  console.log(`[RebuildCandles] Rebuilt ${bars.size} candle bars across all timeframes. Persisting to database...`);

  // Persiste em lotes no Postgres
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const upsertSql = `
      INSERT INTO candles (symbol, interval, bucket_start, open, high, low, close, volume)
      VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
      ON CONFLICT (symbol, interval, bucket_start)
      DO UPDATE SET
        open = EXCLUDED.open,
        high = EXCLUDED.high,
        low = EXCLUDED.low,
        close = EXCLUDED.close,
        volume = EXCLUDED.volume;
    `;

    for (const bar of bars.values()) {
      await client.query(upsertSql, [
        bar.symbol,
        bar.interval,
        bar.bucket_start,
        bar.open,
        bar.high,
        bar.low,
        bar.close,
        bar.volume
      ]);
    }

    await client.query("COMMIT");
    console.log(`[RebuildCandles] Successfully persisted ${bars.size} candles for ${symbol}`);
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }

  return totalProcessed;
}

if (process.argv[1]?.endsWith("rebuild-candles.ts") || process.argv[1]?.endsWith("rebuild-candles.js")) {
  const pool = new Pool({ connectionString: DATABASE_URL });
  rebuildCandlesForSymbol(pool, SYMBOL)
    .then(count => {
      console.log(`[RebuildCandles] Finished! Processed ${count} ticks.`);
      pool.end();
      process.exit(0);
    })
    .catch(err => {
      console.error("[RebuildCandles] Failed:", err);
      pool.end();
      process.exit(1);
    });
}

import { Redis } from "ioredis";

export interface StreamMessage {
  id: string;
  data: Record<string, string>;
}

export class StreamConsumerGroup {
  private redis: Redis;
  private streamKey: string;
  private groupName: string;
  private consumerName: string;

  constructor(redis: Redis, streamKey: string, groupName: string, consumerName: string) {
    this.redis = redis;
    this.streamKey = streamKey;
    this.groupName = groupName;
    this.consumerName = consumerName;
  }

  async init(): Promise<void> {
    try {
      // Cria group iniciando do último id ($) com MKSTREAM para criar se não existir
      await this.redis.xgroup("CREATE", this.streamKey, this.groupName, "$", "MKSTREAM");
    } catch (err: any) {
      if (!err.message?.includes("BUSYGROUP")) {
        throw err;
      }
      // BUSYGROUP significa que o grupo já existe, o que é esperado e idempotente
    }
  }

  async readMessages(count: number = 50, blockMs: number = 1000): Promise<StreamMessage[]> {
    const raw = await this.redis.xreadgroup(
      "GROUP",
      this.groupName,
      this.consumerName,
      "COUNT",
      count,
      "BLOCK",
      blockMs,
      "STREAMS",
      this.streamKey,
      ">"
    );

    if (!raw || !Array.isArray(raw)) return [];

    const messages: StreamMessage[] = [];
    for (const [_stream, entries] of raw as any[]) {
      for (const [id, fields] of entries) {
        const data: Record<string, string> = {};
        for (let i = 0; i < fields.length; i += 2) {
          data[fields[i]] = fields[i + 1];
        }
        messages.push({ id, data });
      }
    }
    return messages;
  }

  async autoClaimPending(minIdleTimeMs: number = 5000, count: number = 50): Promise<StreamMessage[]> {
    try {
      // XAUTOCLAIM stream group consumer min-idle-time start COUNT count
      const res = await this.redis.xautoclaim(
        this.streamKey,
        this.groupName,
        this.consumerName,
        minIdleTimeMs,
        "0-0",
        "COUNT",
        count
      );

      if (!res || !Array.isArray(res) || res.length < 2) return [];

      const entries = res[1] as any[];
      const messages: StreamMessage[] = [];
      for (const [id, fields] of entries) {
        if (!fields) continue;
        const data: Record<string, string> = {};
        for (let i = 0; i < fields.length; i += 2) {
          data[fields[i]] = fields[i + 1];
        }
        messages.push({ id, data });
      }
      return messages;
    } catch (err) {
      return [];
    }
  }

  async ack(messageId: string): Promise<number> {
    return this.redis.xack(this.streamKey, this.groupName, messageId);
  }

  async ackBatch(messageIds: string[]): Promise<number> {
    if (messageIds.length === 0) return 0;
    return this.redis.xack(this.streamKey, this.groupName, ...messageIds);
  }
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { TimeframeAggregator, TIMEFRAMES } from "../src/aggregator/timeframe-aggregator.js";

describe("TimeframeAggregator (OHLCV Calculation)", () => {
  it("calculates correct UTC bucket starts for 1s, 1m and 5m", () => {
    // 2026-10-06T14:02:45.350Z
    const ts = new Date("2026-10-06T14:02:45.350Z");

    const bucket1s = TimeframeAggregator.calculateBucketStart(ts, TIMEFRAMES["1s"]);
    assert.equal(bucket1s.toISOString(), "2026-10-06T14:02:45.000Z");

    const bucket1m = TimeframeAggregator.calculateBucketStart(ts, TIMEFRAMES["1m"]);
    assert.equal(bucket1m.toISOString(), "2026-10-06T14:02:00.000Z");

    const bucket5m = TimeframeAggregator.calculateBucketStart(ts, TIMEFRAMES["5m"]);
    assert.equal(bucket5m.toISOString(), "2026-10-06T14:00:00.000Z");
  });

  it("handles boundary tick at exact minute boundary :00.000Z", () => {
    const tsExact = new Date("2026-10-06T14:03:00.000Z");
    const bucket1m = TimeframeAggregator.calculateBucketStart(tsExact, TIMEFRAMES["1m"]);
    assert.equal(bucket1m.toISOString(), "2026-10-06T14:03:00.000Z");
  });

  it("correctly simulates OHLCV progression over sequential ticks", () => {
    const prices = ["1.485000", "1.485500", "1.484800", "1.485200"];
    let open = prices[0];
    let high = parseFloat(prices[0]);
    let low = parseFloat(prices[0]);
    let close = prices[0];
    let volume = 0;

    for (const p of prices) {
      const pNum = parseFloat(p);
      if (pNum > high) high = pNum;
      if (pNum < low) low = pNum;
      close = p;
      volume++;
    }

    assert.equal(open, "1.485000");
    assert.equal(high, 1.4855);
    assert.equal(low, 1.4848);
    assert.equal(close, "1.485200");
    assert.equal(volume, 4);
  });
});

import pg from "pg";
const { Pool } = pg;
type Pool = pg.Pool;
import crypto from "node:crypto";
import { BlnkClient } from "@broker/wallet-adapter";

export interface ReconciliationReport {
  timestamp: string;
  checks: {
    blnk_zero_sum: boolean;
    open_contracts_vs_reserved: boolean;
    stuck_settling_contracts: boolean;
    failed_outbox_events: boolean;
    tick_sequence_continuous: boolean;
    hash_chain_valid: boolean;
  };
  discrepancies: string[];
  status: "HEALTHY" | "CRITICAL_ALERT";
}

export class FinancialReconciler {
  private pool: Pool;
  private blnkClient: BlnkClient;

  constructor(pool: Pool, blnkClient: BlnkClient) {
    this.pool = pool;
    this.blnkClient = blnkClient;
  }

  async runAudit(): Promise<ReconciliationReport> {
    const report: ReconciliationReport = {
      timestamp: new Date().toISOString(),
      checks: {
        blnk_zero_sum: true,
        open_contracts_vs_reserved: true,
        stuck_settling_contracts: true,
        failed_outbox_events: true,
        tick_sequence_continuous: true,
        hash_chain_valid: true
      },
      discrepancies: [],
      status: "HEALTHY"
    };

    // 1. Checagem: Contratos Abertos vs Stakes
    try {
      const openContractsRes = await this.pool.query(
        `SELECT COUNT(*) as count, COALESCE(SUM(stake_minor), 0) as total_stake
         FROM contracts
         WHERE status = 'OPEN';`
      );
      const totalOpenStake = openContractsRes.rows.length > 0 
        ? parseInt(openContractsRes.rows[0].total_stake, 10) 
        : 0;
      // Registrado no relatório
    } catch (err: any) {
      report.checks.open_contracts_vs_reserved = false;
      report.discrepancies.push(`Failed querying open contracts: ${err.message}`);
    }

    // 2. Checagem: Contratos Presos em Expiração (> 30s após expires_at sem status SETTLED)
    try {
      const stuckRes = await this.pool.query(
        `SELECT id, expires_at, status
         FROM contracts
         WHERE status = 'OPEN'
           AND expires_at < NOW() - INTERVAL '30 seconds';`
      );

      if (stuckRes.rows.length > 0) {
        report.checks.stuck_settling_contracts = false;
        report.discrepancies.push(`Found ${stuckRes.rows.length} contracts stuck past expiration`);
      }
    } catch (err: any) {
      report.checks.stuck_settling_contracts = false;
      report.discrepancies.push(`Failed checking stuck contracts: ${err.message}`);
    }

    // 3. Checagem: Outbox DLQ (eventos FAILED)
    try {
      const failedOutboxRes = await this.pool.query(
        `SELECT id, event_type, retry_count
         FROM outbox_events
         WHERE status = 'FAILED' OR retry_count >= 5;`
      );

      if (failedOutboxRes.rows.length > 0) {
        report.checks.failed_outbox_events = false;
        report.discrepancies.push(`Found ${failedOutboxRes.rows.length} failed outbox events`);
      }
    } catch (err: any) {
      report.checks.failed_outbox_events = false;
      report.discrepancies.push(`Failed checking outbox DLQ: ${err.message}`);
    }

    // 4. Checagem: Sequenciamento de Ticks (M-02)
    try {
      const ticksRes = await this.pool.query(
        `SELECT sequence, price, ts, prev_hash, hash
         FROM ticks
         ORDER BY sequence DESC
         LIMIT 500;`
      );

      const rows = ticksRes.rows;
      if (rows.length > 1) {
        for (let i = 0; i < rows.length - 1; i++) {
          const currentSeq = BigInt(rows[i].sequence);
          const prevSeq = BigInt(rows[i + 1].sequence);

          if (currentSeq !== prevSeq + 1n) {
            report.checks.tick_sequence_continuous = false;
            report.discrepancies.push(`Gap in tick sequence detected between ${prevSeq} and ${currentSeq}`);
            break;
          }

          // 5. Checagem: Encadeamento de Hash SHA-256 (M-04)
          if (rows[i].prev_hash !== rows[i + 1].hash) {
            report.checks.hash_chain_valid = false;
            report.discrepancies.push(`Hash chain mismatch at sequence ${currentSeq}`);
            break;
          }
        }
      }
    } catch (err: any) {
      report.checks.tick_sequence_continuous = false;
      report.checks.hash_chain_valid = false;
      report.discrepancies.push(`Failed verifying tick sequence and hash chain: ${err.message}`);
    }

    if (report.discrepancies.length > 0) {
      report.status = "CRITICAL_ALERT";
    }

    return report;
  }
}

import { Redis } from "ioredis";

export class ExpiryDispatcher {
  private redis: Redis;
  private isRunning: boolean = false;
  private intervalTimer: NodeJS.Timeout | null = null;

  readonly STREAM_KEY = "stream:contracts:expiring";
  readonly GROUP_NAME = "cg:settlement";

  constructor(redis: Redis) {
    this.redis = redis;
  }

  async init(): Promise<void> {
    try {
      await this.redis.xgroup("CREATE", this.STREAM_KEY, this.GROUP_NAME, "$", "MKSTREAM");
    } catch (err: any) {
      if (!err.message?.includes("BUSYGROUP")) {
        throw err;
      }
    }
  }

  start(intervalMs: number = 50): void {
    if (this.isRunning) return;
    this.isRunning = true;

    this.intervalTimer = setInterval(async () => {
      try {
        await this.dispatchExpiredContracts();
      } catch (err) {
        console.error("[ExpiryDispatcher] Error dispatching contracts:", err);
      }
    }, intervalMs);
  }

  stop(): void {
    this.isRunning = false;
    if (this.intervalTimer) {
      clearInterval(this.intervalTimer);
      this.intervalTimer = null;
    }
  }

  async dispatchExpiredContracts(limit: number = 100): Promise<number> {
    const nowMs = Date.now();
    // Busca contratos com expiração <= agora
    const expiredContractIds = await this.redis.zrangebyscore("contracts:pending", 0, nowMs, "LIMIT", 0, limit);

    if (expiredContractIds.length === 0) return 0;

    for (const contractId of expiredContractIds) {
      // Envia para o stream de liquidação (não remove do Sorted Set ainda!)
      await this.redis.xadd(
        this.STREAM_KEY,
        "*",
        "contract_id",
        contractId,
        "dispatched_at",
        nowMs.toString()
      );
    }

    return expiredContractIds.length;
  }
}

import pg from "pg";
const { Pool } = pg;
type Pool = pg.Pool;
import { Redis } from "ioredis";
import { PayoutCalculator, Direction } from "./payout-calculator.js";
import { BlnkClient } from "@broker/wallet-adapter";
import { isMarketOpen } from "./calendar.js";

export class ContractSettler {
  private pool: Pool;
  private redis: Redis;
  private blnkClient: BlnkClient;
  private consumerName: string;

  readonly STREAM_KEY = "stream:contracts:expiring";
  readonly GROUP_NAME = "cg:settlement";

  constructor(pool: Pool, redis: Redis, blnkClient: BlnkClient, consumerName: string) {
    this.pool = pool;
    this.redis = redis;
    this.blnkClient = blnkClient;
    this.consumerName = consumerName;
  }

  /**
   * Processa a liquidação de um contrato específico com bloqueio pessimista (B-08, DB-07, I-04)
   */
  async settleContract(contractId: string): Promise<{ success: boolean; reason?: string }> {
    const client = await this.pool.connect();

    try {
      await client.query("BEGIN");

      // 1. Bloqueio pessimista com SKIP LOCKED para prevenir concorrência entre workers
      const lockRes = await client.query(
        `SELECT id, user_id, symbol, direction, status, stake_minor, entry_price, opened_at, expires_at
         FROM contracts
         WHERE id = $1
         FOR UPDATE SKIP LOCKED;`,
        [contractId]
      );

      if (lockRes.rows.length === 0) {
        // Outro worker já bloqueou ou contrato não existe
        await client.query("COMMIT");
        return { success: false, reason: "ALREADY_LOCKED_OR_NOT_FOUND" };
      }

      const contract = lockRes.rows[0];

      // Idempotência: se já foi liquidado anteriormente, finaliza
      if (contract.status === "SETTLED") {
        await client.query("COMMIT");
        await this.redis.zrem("contracts:pending", contractId);
        return { success: true, reason: "ALREADY_SETTLED" };
      }

      // 2. Validação de Sessão de Mercado (Perigo 7 / Técnica 4)
      if (!isMarketOpen(contract.symbol, contract.expires_at)) {
        await client.query("ROLLBACK");
        return { success: false, reason: "MARKET_CLOSED_AT_EXPIRY" };
      }

      // 3. Busca rigorosa do primeiro tick oficial gravado no PostgreSQL onde ts >= expires_at (B-08)
      const tickRes = await client.query(
        `SELECT sequence, price, ts
         FROM ticks
         WHERE symbol = $1
           AND ts >= $2
         ORDER BY sequence ASC
         LIMIT 1;`,
        [contract.symbol, contract.expires_at]
      );

      if (tickRes.rows.length === 0) {
        // O tick oficial de saída ainda não foi gravado! ROLLBACK para retentar no próximo ciclo (sem inventar preço)
        await client.query("ROLLBACK");
        return { success: false, reason: "EXIT_TICK_NOT_YET_AVAILABLE" };
      }

      const exitTick = tickRes.rows[0];
      if (!isMarketOpen(contract.symbol, exitTick.ts)) {
        await client.query("ROLLBACK");
        return { success: false, reason: "TICK_OUT_OF_SESSION" };
      }

      const exitPrice = exitTick.price.toString();
      const exitSeq = BigInt(exitTick.sequence);

      // 3. Determinação de resultado e cálculo de payout com inteiros (D-19)
      const result = PayoutCalculator.determineResult(
        contract.direction as Direction,
        contract.entry_price.toString(),
        exitPrice
      );

      const stakeMinor = parseInt(contract.stake_minor, 10);
      const calc = PayoutCalculator.calculatePayout(result, stakeMinor);

      // 4. Atualização atômica do status do contrato no PostgreSQL
      await client.query(
        `UPDATE contracts
         SET status = 'SETTLED',
             result = $1,
             exit_price = $2,
             exit_tick_sequence = $3,
             payout_minor = $4,
             settled_at = NOW()
         WHERE id = $5;`,
        [result, exitPrice, exitSeq.toString(), calc.payout_minor, contractId]
      );

      // 5. Inserção do evento de auditoria no Transactional Outbox
      const outboxPayload = JSON.stringify({
        contract_id: contractId,
        user_id: contract.user_id,
        symbol: contract.symbol,
        direction: contract.direction,
        entry_price: contract.entry_price.toString(),
        exit_price: exitPrice,
        exit_tick_sequence: exitSeq.toString(),
        result,
        stake_minor: stakeMinor,
        payout_minor: calc.payout_minor,
        profit_minor: calc.profit_minor
      });

      await client.query(
        `INSERT INTO outbox_events (event_type, payload, status)
         VALUES ('CONTRACT_SETTLED', $1, 'PENDING');`,
        [outboxPayload]
      );

      await client.query("COMMIT");

      // 6. Pós-Commit: remove do Sorted Set de pendências
      await this.redis.zrem("contracts:pending", contractId);

      // 7. Liberação contábil no Blnk Ledger (partidas dobradas)
      try {
        await this.blnkClient.settleContract(
          contractId,
          contract.user_id,
          result,
          stakeMinor,
          calc.payout_minor
        );
      } catch (blnkErr) {
        console.error(`[Settler] Warning: Blnk ledger settlement failed for ${contractId}:`, blnkErr);
      }

      // 8. Publica no Redis Pub/Sub para notificação imediata do WebSocket Gateway
      await this.redis.publish(`market:events:${contract.symbol}`, JSON.stringify({
        event: "CONTRACT_SETTLED",
        contract_id: contractId,
        user_id: contract.user_id,
        result,
        payout_minor: calc.payout_minor,
        exit_price: exitPrice
      }));

      return { success: true };
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }
  }

  /**
   * Consome lote do Redis Stream com XREADGROUP e processa cada contrato
   */
  async processBatch(count: number = 20, blockMs: number = 1000): Promise<number> {
    const raw = await this.redis.xreadgroup(
      "GROUP",
      this.GROUP_NAME,
      this.consumerName,
      "COUNT",
      count,
      "BLOCK",
      blockMs,
      "STREAMS",
      this.STREAM_KEY,
      ">"
    );

    if (!raw || !Array.isArray(raw)) return 0;

    let processedCount = 0;

    for (const [_stream, entries] of raw as any[]) {
      for (const [msgId, fields] of entries) {
        let contractId = "";
        for (let i = 0; i < fields.length; i += 2) {
          if (fields[i] === "contract_id") {
            contractId = fields[i + 1];
            break;
          }
        }

        if (contractId) {
          const outcome = await this.settleContract(contractId);
          // Se liquidou com sucesso ou já estava liquidado, confirma mensagem no Stream
          if (outcome.success) {
            await this.redis.xack(this.STREAM_KEY, this.GROUP_NAME, msgId);
            processedCount++;
          }
          // Se o tick ainda não estava disponível, NÃO damos XACK (reprocessará após tick chegar)
        } else {
          await this.redis.xack(this.STREAM_KEY, this.GROUP_NAME, msgId);
        }
      }
    }

    return processedCount;
  }
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { FinancialReconciler } from "../src/reconciliation/financial-reconciler.js";

describe("FinancialReconciler (Continuous Audit & Hash Integrity)", () => {
  it("reports HEALTHY when ticks and contracts are consistent", async () => {
    const mockPool = {
      query: async (sql: string, params: any[]) => {
        const clean = sql.replace(/\s+/g, " ");
        if (clean.includes("INTERVAL '30 seconds'")) {
          return { rows: [] }; // Nenhum preso
        }
        if (clean.includes("COALESCE(SUM(stake_minor), 0)")) {
          return { rows: [{ count: "0", total_stake: "0" }] };
        }
        if (clean.includes("FROM outbox_events")) {
          return { rows: [] }; // Nenhuma falha
        }
        if (clean.includes("FROM ticks")) {
          return {
            rows: [
              { sequence: "100", prev_hash: "hash-99", hash: "hash-100" },
              { sequence: "99", prev_hash: "hash-98", hash: "hash-99" }
            ]
          };
        }
        return { rows: [] };
      }
    };

    const mockBlnk = {} as any;
    const reconciler = new FinancialReconciler(mockPool as any, mockBlnk);
    const report = await reconciler.runAudit();

    assert.equal(report.status, "HEALTHY");
    assert.equal(report.discrepancies.length, 0);
    assert.equal(report.checks.tick_sequence_continuous, true);
    assert.equal(report.checks.hash_chain_valid, true);
  });

  it("triggers CRITICAL_ALERT when sequence has gaps or hash chain is broken", async () => {
    const mockPool = {
      query: async (sql: string, params: any[]) => {
        const clean = sql.replace(/\s+/g, " ");
        if (clean.includes("INTERVAL '30 seconds'")) {
          return { rows: [] };
        }
        if (clean.includes("COALESCE(SUM(stake_minor), 0)")) {
          return { rows: [{ count: "0", total_stake: "0" }] };
        }
        if (clean.includes("FROM outbox_events")) {
          return { rows: [] };
        }
        if (clean.includes("FROM ticks")) {
          return {
            rows: [
              { sequence: "105", prev_hash: "hash-104", hash: "hash-105" },
              // Gap de 100 para 105!
              { sequence: "100", prev_hash: "hash-99", hash: "hash-100" }
            ]
          };
        }
        return { rows: [] };
      }
    };

    const mockBlnk = {} as any;
    const reconciler = new FinancialReconciler(mockPool as any, mockBlnk);
    const report = await reconciler.runAudit();

    assert.equal(report.status, "CRITICAL_ALERT");
    assert.equal(report.checks.tick_sequence_continuous, false);
    assert.ok(report.discrepancies.some(d => d.includes("Gap in tick sequence")));
  });

  it("triggers CRITICAL_ALERT when contracts are stuck past expiration", async () => {
    const mockPool = {
      query: async (sql: string, params: any[]) => {
        const clean = sql.replace(/\s+/g, " ");
        if (clean.includes("INTERVAL '30 seconds'")) {
          return { rows: [{ id: "stuck-1", expires_at: new Date() }] };
        }
        if (clean.includes("COALESCE(SUM(stake_minor), 0)")) {
          return { rows: [{ count: "1", total_stake: "1000" }] };
        }
        if (clean.includes("FROM outbox_events")) {
          return { rows: [] };
        }
        if (clean.includes("FROM ticks")) {
          return { rows: [] };
        }
        return { rows: [] };
      }
    };

    const mockBlnk = {} as any;
    const reconciler = new FinancialReconciler(mockPool as any, mockBlnk);
    const report = await reconciler.runAudit();

    assert.equal(report.status, "CRITICAL_ALERT");
    assert.equal(report.checks.stuck_settling_contracts, false);
    assert.ok(report.discrepancies.some(d => d.includes("contracts stuck past expiration")));
  });
});

