                  expires_at: new Date(Date.now())
                }
              ]
            };
          }
          if (sql.includes("FROM ticks")) {
            return {
              rows: [
                {
                  sequence: "1050",
                  price: "1.485600", // Preço subiu => UP ganha (WIN)
                  ts: new Date()
                }
              ]
            };
          }
          if (sql.includes("UPDATE contracts")) {
            updatedStatus = params[0]; // Result WIN
            return {};
          }
          if (sql.includes("INSERT INTO outbox_events")) {
            return {};
          }
          return { rows: [] };
        },
        release: () => {}
      })
