import { randomUUID } from 'node:crypto';
import Redis from 'ioredis';
import pg from 'pg';
import { Counter, Gauge, Registry } from 'prom-client';
import { createServer } from 'node:http';
import { canonicalHash, createPriceGenerator, nextSequence } from './core.mjs';

const defaultSymbol = process.env.TICK_SYMBOL ?? 'SYNTH_VOL_50';
const redis = new Redis(process.env.REDIS_URL ?? 'redis://redis:6379', {
  lazyConnect: true,
  commandTimeout: 2000,
  maxRetriesPerRequest: 1,
  enableOfflineQueue: false,
});

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL_TICK,
  connectionTimeoutMillis: 3000,
  statement_timeout: 3000,
  query_timeout: 3000,
  max: process.env.DB_POOL_MAX ? parseInt(process.env.DB_POOL_MAX, 10) : 10,
});

const registry = new Registry();
export const metrics = {
  leader: new Gauge({ name: 'tick_engine_is_leader', help: 'Current leader state', labelNames: ['symbol'], registers: [registry] }),
  age: new Gauge({ name: 'tick_engine_last_tick_age_seconds', help: 'Age of last tick', labelNames: ['symbol'], registers: [registry] }),
  ticks: new Counter({ name: 'tick_engine_ticks_total', help: 'Persisted ticks', labelNames: ['symbol'], registers: [registry] }),
  errors: new Counter({ name: 'tick_engine_errors_total', help: 'Tick engine errors', labelNames: ['symbol'], registers: [registry] }),
};

redis.on('error', () => { metrics.errors.inc({ symbol: 'redis' }); });
pool.on('error', () => { metrics.errors.inc({ symbol: 'pool' }); });

const owner = randomUUID();
const renewLua = 'if redis.call("GET",KEYS[1]) == ARGV[1] then return redis.call("PEXPIRE",KEYS[1],ARGV[2]) else return 0 end';
const releaseLua = 'if redis.call("GET",KEYS[1]) == ARGV[1] then return redis.call("DEL",KEYS[1]) else return 0 end';
const generate = createPriceGenerator();

export class SymbolState {
  constructor(symbol) {
    this.symbol = symbol;
    this.leaseKey = `lease:tick-engine:${symbol}`;
    this.epochKey = `lease:epoch:${symbol}`;
    this.epoch = null;
    this.ownedEpoch = null;
    this.lastTickAt = null;
  }
}

export const symbolStates = new Map();

export function getSymbolState(symbol) {
  let state = symbolStates.get(symbol);
  if (!state) {
    state = new SymbolState(symbol);
    symbolStates.set(symbol, state);
  }
  return state;
}

export async function releaseLeadership(targetSymbol = defaultSymbol) {
  const state = getSymbolState(targetSymbol);
  state.ownedEpoch = null;
  state.epoch = null;
  metrics.leader.set({ symbol: targetSymbol }, 0);
  try {
    if (redis.status === 'ready' || redis.status === 'connect') {
      await redis.eval(releaseLua, 1, state.leaseKey, owner);
    }
  } catch {
    // Ignore error on shutdown
  }
}

export async function renewLeasesInBackground(runningRef = { running: true }) {
  while (runningRef.running) {
    await new Promise((resolve) => setTimeout(resolve, 500));
    const activeStates = [...symbolStates.values()].filter((st) => st.epoch !== null);
    if (activeStates.length === 0) continue;

    try {
      if (redis.status === 'wait') await redis.connect();
      const pipeline = redis.pipeline();
      for (const st of activeStates) {
        pipeline.eval(renewLua, 1, st.leaseKey, owner, 3000);
      }
      const results = await pipeline.exec();
      if (!results) continue;

      for (let i = 0; i < activeStates.length; i++) {
        const [err, res] = results[i];
        const st = activeStates[i];
        if (err || res !== 1) {
          process.stderr.write(`LEASE_LOST ${st.symbol} ${st.epoch}\n`);
          st.epoch = null;
          metrics.leader.set({ symbol: st.symbol }, 0);
        }
      }
    } catch (error) {
      metrics.errors.inc({ symbol: 'batch_renew' });
      process.stderr.write(`LEASE_RENEW_ERROR ${error?.message ?? 'UNKNOWN'}\n`);
    }
  }
}

export async function claimLease(targetSymbol = defaultSymbol) {
  if (redis.status === 'wait') await redis.connect();
  const state = getSymbolState(targetSymbol);

  // Attempt to acquire Redis lease (PX 3000ms, NX)
  if ((await redis.set(state.leaseKey, owner, 'PX', 3000, 'NX')) !== 'OK') {
    return null;
  }

  if (state.ownedEpoch !== null) {
    state.epoch = state.ownedEpoch;
    metrics.leader.set({ symbol: targetSymbol }, 1);
    return state.epoch;
  }

  const acquiredEpoch = await redis.incr(state.epochKey);

  // Acquire client only for state check and lease update, releasing immediately
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const dbState = await client.query(
      'SELECT last_sequence, last_hash FROM index_state WHERE symbol = $1 FOR UPDATE',
      [targetSymbol]
    );
    if (dbState.rowCount !== 1) throw new Error('INDEX_STATE_MISSING');

    const latest = await client.query(
      'SELECT sequence, hash FROM ticks WHERE symbol = $1 ORDER BY sequence DESC LIMIT 1',
      [targetSymbol]
    );
    if (
      latest.rowCount &&
      (String(latest.rows[0].sequence) !== String(dbState.rows[0].last_sequence) ||
        latest.rows[0].hash !== dbState.rows[0].last_hash)
    ) {
      throw new Error('INDEX_STATE_DIVERGED');
    }

    await client.query(
      'UPDATE index_state SET lease_epoch = $1 WHERE symbol = $2',
      [acquiredEpoch, targetSymbol]
    );
    await client.query('COMMIT');

    state.epoch = acquiredEpoch;
    state.ownedEpoch = acquiredEpoch;
    process.stderr.write(`LEASE_ACQUIRED ${targetSymbol} ${state.epoch}\n`);
    metrics.leader.set({ symbol: targetSymbol }, 1);
    return state.epoch;
  } catch (error) {
    await client.query('ROLLBACK');
    await redis.eval(releaseLua, 1, state.leaseKey, owner);
    await releaseLeadership(targetSymbol);
    throw error;
  } finally {
    client.release();
  }
}

export async function persistTick(targetSymbol = defaultSymbol) {
  const state = getSymbolState(targetSymbol);
  if (state.epoch === null || (await redis.eval(renewLua, 1, state.leaseKey, owner, 3000)) !== 1) {
    state.epoch = null;
    metrics.leader.set({ symbol: targetSymbol }, 0);
    return false;
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await client.query(
      `SELECT s.last_sequence, s.last_price, s.last_hash, s.last_ts, s.lease_epoch,
              i.params, i.status FROM index_state s JOIN indices i USING (symbol)
       WHERE s.symbol = $1 FOR UPDATE OF s`,
      [targetSymbol]
    );
    if (result.rowCount !== 1) throw new Error('INDEX_STATE_MISSING');
    const row = result.rows[0];
    if (Number(row.lease_epoch) !== state.epoch) throw new Error('FENCED');

    const sigma = Number(row.params.sigma);
    const precision = Number(row.params.precision);
    if (
      !Number.isFinite(sigma) ||
      sigma <= 0 ||
      !Number.isInteger(precision) ||
      precision < 0 ||
      precision > 6
    ) {
      throw new Error('INDEX_PARAMS_MISSING');
    }

    // PAUSED indices still emit official ticks for open contracts.
    const sequence = nextSequence(row.last_sequence);
    const now = new Date(Math.max(Date.now(), new Date(row.last_ts).getTime() + 1)).toISOString();
    const price = generate(String(row.last_price), sigma, precision);
    const prevHash = row.last_hash;
    const hash = canonicalHash(prevHash, targetSymbol, sequence, now, price);
    const tick = {
      symbol: targetSymbol,
      sequence,
      ts: now,
      price,
      prev_hash: prevHash,
      hash,
      lease_epoch: state.epoch,
    };

    await client.query(
      'INSERT INTO ticks (symbol, sequence, ts, price, prev_hash, hash, lease_epoch) VALUES ($1,$2,$3,$4,$5,$6,$7)',
      [targetSymbol, sequence, now, price, prevHash, hash, state.epoch]
    );
    await client.query(
      'UPDATE index_state SET last_sequence=$1,last_price=$2,last_hash=$3,last_ts=$4 WHERE symbol=$5 AND lease_epoch=$6',
      [sequence, price, hash, now, targetSymbol, state.epoch]
    );
    await client.query(
      'INSERT INTO outbox (topic, aggregate_id, sequence, dedupe_key, payload) VALUES ($1,$2,$3,$4,$5)',
      ['tick', targetSymbol, sequence, `tick:${targetSymbol}:${sequence}`, tick]
    );
    await client.query('COMMIT');

    metrics.ticks.inc({ symbol: targetSymbol });
    state.lastTickAt = Date.parse(now);
    return true;
  } catch (error) {
    await client.query('ROLLBACK');
    metrics.errors.inc({ symbol: targetSymbol });
    throw error;
  } finally {
    client.release();
  }
}

export async function discoverActiveSymbols(poolInstance = pool) {
  const res = await poolInstance.query(
    "SELECT symbol, params, status FROM indices WHERE status IN ('ACTIVE', 'PAUSED') ORDER BY symbol ASC"
  );
  return res.rows.map((r) => r.symbol);
}

async function main() {
  if (!process.env.DATABASE_URL_TICK) throw new Error('DATABASE_URL_TICK_REQUIRED');

  createServer(async (_request, response) => {
    const now = Date.now();
    for (const [sym, st] of symbolStates) {
      if (st.lastTickAt !== null) {
        metrics.age.set({ symbol: sym }, Math.max(0, (now - st.lastTickAt) / 1000));
      }
    }
    response.writeHead(200, { 'content-type': registry.contentType });
    response.end(await registry.metrics());
  }).listen(9100);

  const runningRef = { running: true };
  process.on('SIGTERM', () => { runningRef.running = false; });

  const renewal = renewLeasesInBackground(runningRef);

  const isMultiSymbol = !process.env.TICK_SYMBOL || process.env.TICK_SYMBOL === 'ALL';

  if (!isMultiSymbol) {
    // Single symbol mode (backward compatibility)
    while (runningRef.running) {
      const state = getSymbolState(defaultSymbol);
      const wait = state.epoch === null ? 100 : Math.max(1, 1000 - (Date.now() % 1000));
      await new Promise((resolve) => setTimeout(resolve, wait));
      try {
        if (state.epoch === null) await claimLease(defaultSymbol);
        else await persistTick(defaultSymbol);
      } catch (error) {
        metrics.errors.inc({ symbol: defaultSymbol });
        process.stderr.write(`${error?.message ?? 'TICK_ERROR'}\n`);
        if (error?.message === 'FENCED') {
          await releaseLeadership(defaultSymbol);
        }
      }
    }
  } else {
    // Dynamic multi-symbol mode
    let lastDiscovery = 0;
    let activeSymbols = [];

    while (runningRef.running) {
      const now = Date.now();
      if (now - lastDiscovery > 5000) {
        try {
          activeSymbols = await discoverActiveSymbols(pool);
          lastDiscovery = now;
        } catch (error) {
          metrics.errors.inc({ symbol: 'discovery' });
        }
      }

      if (activeSymbols.length === 0) {
        await new Promise((resolve) => setTimeout(resolve, 500));
        continue;
      }

      for (const sym of activeSymbols) {
        const state = getSymbolState(sym);
        try {
          if (state.epoch === null) {
            await claimLease(sym);
          } else {
            // Check if 1000ms has elapsed for this symbol
            if (!state.lastTickAt || now - state.lastTickAt >= 990) {
              await persistTick(sym);
            }
          }
        } catch (error) {
          metrics.errors.inc({ symbol: sym });
          if (error?.message === 'FENCED') {
            await releaseLeadership(sym);
          }
        }
      }

      // Small tick resolution sleep (staggered loop)
      const nextSleep = Math.max(10, Math.floor(1000 / Math.max(1, activeSymbols.length)));
      await new Promise((resolve) => setTimeout(resolve, Math.min(nextSleep, 50)));
    }
  }

  await renewal;
  for (const sym of symbolStates.keys()) {
    await releaseLeadership(sym);
  }
  await Promise.all([redis.quit(), pool.end()]);
}

if (process.argv[1]?.endsWith('/engine.mjs')) {
  await main();
}

export interface BlnkTransactionPayload {
  amount: number;
  precision: number;
  currency: string;
  source: string;
  destination: string;
  reference: string;
  description?: string;
  allow_overdraft?: boolean;
}

export interface BlnkBalanceResponse {
  balance: number;
  credit_balance: number;
  debit_balance: number;
  currency: string;
}

export class BlnkClient {
  private baseUrl: string;
  private timeoutMs: number;
  private failureCount: number = 0;
  private circuitOpenUntil: number = 0;
  private readonly maxFailures: number = 5;
  private readonly resetTimeoutMs: number = 10000;

  readonly LEDGER_ID = "broker_demo";
  readonly HOUSE_REVENUE = "@house_revenue";
  readonly HOUSE_PAYOUT = "@house_payout";
  readonly BROKER_FLOAT = "@broker_float";
  readonly DEMO_START_BALANCE_MINOR = 1_000_000; // US$ 10.000,00 em centavos (D-11, D-18)

  constructor(baseUrl: string = process.env.BLNK_URL || "http://localhost:5001", timeoutMs: number = 3000) {
    this.baseUrl = baseUrl.replace(/\/$/, "");
    this.timeoutMs = timeoutMs;
  }

  private isCircuitOpen(): boolean {
    if (this.circuitOpenUntil > Date.now()) {
      return true;
    }
    return false;
  }

  private recordSuccess() {
    this.failureCount = 0;
    this.circuitOpenUntil = 0;
  }

  private recordFailure() {
    this.failureCount++;
    if (this.failureCount >= this.maxFailures) {
      this.circuitOpenUntil = Date.now() + this.resetTimeoutMs;
      console.warn(`[BlnkClient] Circuit Breaker tripped OPEN for ${this.resetTimeoutMs}ms`);
    }
  }

  private async request<T>(path: string, options: RequestInit = {}): Promise<T> {
    if (this.isCircuitOpen()) {
      throw new Error("CIRCUIT_BREAKER_OPEN: Blnk service temporarily unavailable");
    }

    const url = `${this.baseUrl}${path}`;
    let attempt = 0;
    const maxAttempts = 3;

    while (attempt < maxAttempts) {
      attempt++;
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), this.timeoutMs);

      try {
        const response = await fetch(url, {
          ...options,
          signal: controller.signal,
          headers: {
            "Content-Type": "application/json",
            ...options.headers
          }
        });

        clearTimeout(timer);

        if (!response.ok) {
          const body = await response.text();
          // Se for erro de idempotência ou conflito conhecido, não retenta
          if (response.status === 409 || response.status === 422) {
            throw new Error(`BLNK_CLIENT_ERROR_${response.status}: ${body}`);
          }
          throw new Error(`BLNK_HTTP_ERROR_${response.status}: ${body}`);
        }

        this.recordSuccess();
        const data = (await response.json()) as T;
        return data;
      } catch (err: any) {
        clearTimeout(timer);
        if (attempt >= maxAttempts || err.message?.startsWith("BLNK_CLIENT_ERROR")) {
          this.recordFailure();
          throw err;
        }
        // Exponential backoff com jitter: 50ms * 2^attempt + jitter
        const backoff = 50 * Math.pow(2, attempt) + Math.floor(Math.random() * 30);
        await new Promise(r => setTimeout(r, backoff));
      }
    }

    throw new Error("BLNK_MAX_RETRIES_EXCEEDED");
  }

  /**
   * Garante a inicialização das contas da casa e ledger
   */
  async initializeLedgerAndHouseAccounts(): Promise<void> {
    try {
      await this.request("/ledgers", {
        method: "POST",
        body: JSON.stringify({ name: "Broker Demo Ledger", id: this.LEDGER_ID })
      });
    } catch {
      // Ignora se o ledger já existe
    }

    const accounts = [
      { name: "House Revenue", number: this.HOUSE_REVENUE, ledger_id: this.LEDGER_ID, currency: "USD" },
      { name: "House Payout", number: this.HOUSE_PAYOUT, ledger_id: this.LEDGER_ID, currency: "USD" },
      { name: "Broker Float", number: this.BROKER_FLOAT, ledger_id: this.LEDGER_ID, currency: "USD" }
    ];

    for (const acc of accounts) {
      try {
        await this.request("/accounts", {
          method: "POST",
          body: JSON.stringify(acc)
        });
      } catch {
        // Ignora se conta já existe
      }
    }
  }

  /**
   * Onboarding do usuário com criação de contas e US$ 10.000 demo (D-11, I-01)
   */
  async onboardUser(userId: string): Promise<void> {
    const availableAcc = `@user_${userId}:available`;
    const reservedAcc = `@user_${userId}:reserved`;

    // 1. Cria conta disponível
    try {
      await this.request("/accounts", {
        method: "POST",
        body: JSON.stringify({
          name: `User ${userId} Available`,
          number: availableAcc,
          ledger_id: this.LEDGER_ID,
          currency: "USD"
        })
      });
    } catch {
      // Já criada
    }

    // 2. Cria conta de garantia
    try {
      await this.request("/accounts", {
        method: "POST",
        body: JSON.stringify({
          name: `User ${userId} Reserved`,
          number: reservedAcc,
          ledger_id: this.LEDGER_ID,
          currency: "USD"
        })
      });
    } catch {
      // Já criada
    }

    // 3. Credita saldo inicial demo de US$ 10.000,00 com referência idempotente
    try {
      await this.recordTransaction({
        amount: this.DEMO_START_BALANCE_MINOR,
        precision: 100,
        currency: "USD",
        source: this.BROKER_FLOAT,
        destination: availableAcc,
        reference: `onboarding:${userId}`,
        description: "Initial Demo Balance US$ 10,000",
        allow_overdraft: true
      });
    } catch (err: any) {
      // Se a transação já foi processada anteriormente (idempotência), ignorar erro
      if (!err.message?.includes("409") && !err.message?.includes("conflict")) {
        throw err;
      }
    }
  }

  /**
   * Reserva a stake do usuário movendo de available para reserved (I-03)
   */
  async reserveStake(userId: string, contractId: string, stakeMinor: number): Promise<void> {
    await this.recordTransaction({
      amount: stakeMinor,
      precision: 100,
      currency: "USD",
      source: `@user_${userId}:available`,
      destination: `@user_${userId}:reserved`,
      reference: `reserve:${contractId}`,
      description: `Stake reservation for contract ${contractId}`,
      allow_overdraft: false
    });
  }

  /**
   * Reverte reserva de stake em caso de cancelamento da ordem
   */
  async releaseReservedStake(userId: string, contractId: string, stakeMinor: number): Promise<void> {
    await this.recordTransaction({
      amount: stakeMinor,
      precision: 100,
      currency: "USD",
      source: `@user_${userId}:reserved`,
      destination: `@user_${userId}:available`,
      reference: `reversal:reserve:${contractId}`,
      description: `Reversal of stake reservation for contract ${contractId}`,
      allow_overdraft: false
    });
  }

  /**
   * Liquidação financeira no Blnk Ledger (D-19, I-04, I-05)
   */
  async settleContract(
    contractId: string,
    userId: string,
    result: "WIN" | "LOSS" | "DRAW",
    stakeMinor: number,
    payoutMinor: number
  ): Promise<void> {
    const userReserved = `@user_${userId}:reserved`;
    const userAvailable = `@user_${userId}:available`;

    if (result === "LOSS") {
      // Perda: move a stake reservada para a conta de receita da casa
      await this.recordTransaction({
        amount: stakeMinor,
        precision: 100,
        currency: "USD",
        source: userReserved,
        destination: this.HOUSE_REVENUE,
        reference: `settlement:${contractId}:LOSS`,
        description: `Loss settlement for contract ${contractId}`,
        allow_overdraft: false
      });
    } else if (result === "WIN") {
      // Vitória: 
      // 1. Devolve a stake reservada de volta para a carteira disponível
      await this.recordTransaction({
        amount: stakeMinor,
        precision: 100,
        currency: "USD",
        source: userReserved,
        destination: userAvailable,
        reference: `settlement:${contractId}:WIN_STAKE`,
        description: `Stake refund on WIN for contract ${contractId}`,
        allow_overdraft: false
      });

      // 2. Transfere o lucro (payout - stake) da conta da casa para o usuário
      const profitMinor = payoutMinor - stakeMinor;
      if (profitMinor > 0) {
        await this.recordTransaction({
          amount: profitMinor,
          precision: 100,
          currency: "USD",
          source: this.HOUSE_PAYOUT,
          destination: userAvailable,
          reference: `settlement:${contractId}:WIN_PROFIT`,
          description: `Profit payout for contract ${contractId}`,
          allow_overdraft: true
        });
      }
    } else if (result === "DRAW") {
      // Empate: devolve a stake integralmente
      await this.recordTransaction({
        amount: stakeMinor,
        precision: 100,
        currency: "USD",
        source: userReserved,
        destination: userAvailable,
        reference: `settlement:${contractId}:DRAW`,
        description: `Draw refund for contract ${contractId}`,
        allow_overdraft: false
      });
    }
  }

  /**
   * Consulta o saldo disponível do usuário no Blnk (D-02, I-01)
   */
  async getBalance(userId: string): Promise<{ available_minor: number; reserved_minor: number }> {
    const availableAcc = `@user_${userId}:available`;
    const reservedAcc = `@user_${userId}:reserved`;

    const [availRes, resRes] = await Promise.all([
      this.request<BlnkBalanceResponse>(`/balances/${availableAcc}`),
      this.request<BlnkBalanceResponse>(`/balances/${reservedAcc}`)
    ]);

    return {
      available_minor: availRes.balance,
      reserved_minor: resRes.balance
    };
  }

  private async recordTransaction(payload: BlnkTransactionPayload): Promise<any> {
    return this.request("/transactions", {
      method: "POST",
      body: JSON.stringify(payload)
    });
  }
}

/**
 * Backpressure Guard para WebSocket Gateway (Padrão de Resiliência contra Clientes Lentos)
 * 
 * Regras:
 * - Buffer limite por socket: 64KB (65536 bytes)
 * - Se bufferedAmount > 64KB: pausa envio de ticks para o socket
 * - Se socket.bufferedAmount drena: retoma envio
 * - Se permanecer saturado por mais de 5s: desconecta o cliente com código 4429
 */

export interface BackpressureConfig {
  maxBufferedBytes?: number;     // Padrão: 64KB (65536 bytes)
  slowClientTimeoutMs?: number;  // Padrão: 5000ms (5 segundos)
}

export type SocketLike = {
  bufferedAmount: number;
  readyState: number;
  close(code?: number, reason?: string): void;
  on?(event: string, listener: (...args: any[]) => void): void;
};

export class BackpressureGuard {
  private readonly maxBufferedBytes: number;
  private readonly slowClientTimeoutMs: number;
  private saturatedSockets = new Map<SocketLike, number>();
  private pausedCount = 0;
  private disconnectedCount = 0;

  constructor(
    config: BackpressureConfig = {},
    private readonly timeFn: () => number = Date.now
  ) {
    this.maxBufferedBytes = config.maxBufferedBytes ?? 64 * 1024;
    this.slowClientTimeoutMs = config.slowClientTimeoutMs ?? 5000;
  }

  /**
   * Avalia se o socket está em condições de receber novos dados sem saturação de memória.
   */
  public shouldSend(socket: SocketLike): boolean {
    if (socket.readyState !== 1) return false;

    if (socket.bufferedAmount > this.maxBufferedBytes) {
      const now = this.timeFn();
      if (!this.saturatedSockets.has(socket)) {
        this.saturatedSockets.set(socket, now);
        this.pausedCount++;
      } else {
        const saturatedDuration = now - (this.saturatedSockets.get(socket) ?? now);
        if (saturatedDuration >= this.slowClientTimeoutMs) {
          this.disconnectSlowClient(socket);
          return false;
        }
      }
      return false; // Pausa envio para proteger a memória do gateway
    }

    // Buffer normalizado
    if (this.saturatedSockets.has(socket)) {
      this.saturatedSockets.delete(socket);
      if (this.pausedCount > 0) this.pausedCount--;
    }

    return true;
  }

  /**
   * Trata o evento de drenagem de buffer do socket TCP.
   */
  public handleDrain(socket: SocketLike): void {
    if (this.saturatedSockets.has(socket)) {
      this.saturatedSockets.delete(socket);
      if (this.pausedCount > 0) this.pausedCount--;
    }
  }

  /**
   * Varre e expulsa clientes saturados que excederam o deadline de 5s.
   */
  public checkAndPurgeSlowClients(): number {
    const now = this.timeFn();
    let purged = 0;
    for (const [socket, startTime] of this.saturatedSockets.entries()) {
      if (now - startTime >= this.slowClientTimeoutMs) {
        this.disconnectSlowClient(socket);
        purged++;
      }
    }
    return purged;
  }

  private disconnectSlowClient(socket: SocketLike): void {
    this.saturatedSockets.delete(socket);
    if (this.pausedCount > 0) this.pausedCount--;
    this.disconnectedCount++;
    try {
      socket.close(4429, 'Slow client backpressure timeout');
    } catch {
      // Ignora erro ao fechar
    }
  }

  public getPausedCount(): number {
    return this.pausedCount;
  }

  public getDisconnectedCount(): number {
    return this.disconnectedCount;
  }

  public getMaxBufferedBytes(): number {
    return this.maxBufferedBytes;
  }
}

import { Redis } from "ioredis";

export interface CatchupResult {
  resyncRequired: boolean;
  ticks: Array<{
    symbol: string;
    sequence: string;
    price: string;
    ts: string;
  }>;
}

export class CatchupHandler {
  private redis: Redis;
  readonly MAX_CATCHUP_BUFFER = 1000;

  constructor(redis: Redis) {
    this.redis = redis;
  }

  async getCatchupTicks(symbol: string, clientLastSequence: bigint): Promise<CatchupResult> {
    const streamKey = `stream:ticks:${symbol}`;

    // Busca o tick mais recente no stream para calcular o gap
    const latestEntries = await this.redis.xrevrange(streamKey, "+", "-", "COUNT", 1);
    if (!latestEntries || latestEntries.length === 0) {
      return { resyncRequired: false, ticks: [] };
    }

    const latestFields = latestEntries[0][1];
    let latestSequence = 0n;
    for (let i = 0; i < latestFields.length; i += 2) {
      if (latestFields[i] === "sequence") {
        latestSequence = BigInt(latestFields[i + 1]);
        break;
      }
    }

    const gap = latestSequence - clientLastSequence;
    if (gap <= 0n) {
      return { resyncRequired: false, ticks: [] };
    }

    if (gap > BigInt(this.MAX_CATCHUP_BUFFER)) {
      // Gap maior que 1.000 ticks: força resync completo via HTTP REST
      return { resyncRequired: true, ticks: [] };
    }

    // Lê os últimos N ticks do stream
    const rawEntries = await this.redis.xrevrange(streamKey, "+", "-", "COUNT", Number(gap));
    const ticks: CatchupResult["ticks"] = [];

    for (const [_id, fields] of rawEntries.reverse()) {
      const data: Record<string, string> = {};
      for (let i = 0; i < fields.length; i += 2) {
        data[fields[i]] = fields[i + 1];
      }

      const seq = BigInt(data.sequence || "0");
      if (seq > clientLastSequence) {
        ticks.push({
          symbol: data.symbol || symbol,
          sequence: data.sequence,
          price: data.price,
          ts: data.ts
        });
      }
    }

    return { resyncRequired: false, ticks };
  }
}

import Fastify from "fastify";
import websocket from "@fastify/websocket";
import { Redis } from "ioredis";
import { jwtVerify, createRemoteJWKSet } from "jose";
import { RED_ZONE_COUNTRIES } from "@broker/shared";
import { CatchupHandler } from "./handlers/catchup-handler.js";

const PORT = parseInt(process.env.WS_PORT || "3001", 10);
const HOST = process.env.WS_HOST || "0.0.0.0";
const REDIS_URL = process.env.REDIS_URL || "redis://localhost:6379";
const KEYCLOAK_URL = process.env.KEYCLOAK_URL || "http://localhost:8080";
const REALM = process.env.KEYCLOAK_REALM || "broker-demo";

const app = Fastify({ logger: { level: process.env.LOG_LEVEL || "info" } });

const redisSub = new Redis(REDIS_URL);
const redisClient = new Redis(REDIS_URL);
const catchupHandler = new CatchupHandler(redisClient);

// Mapa de conexões ativas por usuário para aplicar o limite de 5 conexões (B-16)
const activeConnectionsByUser = new Map<string, Set<any>>();
// Mapa de subscrições: symbol -> Set de sockets
const subscriptionsBySymbol = new Map<string, Set<any>>();

// JWKS para validação RS256
let JWKS: any = null;
try {
  const jwksUri = new URL(`${KEYCLOAK_URL}/realms/${REALM}/protocol/openid-connect/certs`);
  JWKS = createRemoteJWKSet(jwksUri);
} catch {
  // Ignora em ambientes de inicialização sem keycloak ativo
}

async function verifyToken(token: string): Promise<{ userId: string; roles: string[] } | null> {
  if (!JWKS) {
    // Modo teste/desenvolvimento fallback
    return { userId: "demo-user-id", roles: ["USER"] };
  }
  try {
    const { payload } = await jwtVerify(token, JWKS, {
      issuer: `${KEYCLOAK_URL}/realms/${REALM}`,
      algorithms: ["RS256"]
    });
    const roles = (payload.realm_access as { roles?: string[] })?.roles || [];
    return { userId: payload.sub as string, roles };
  } catch {
    return null;
  }
}

async function main() {
  await app.register(websocket);

  // Escuta ticks do Redis Pub/Sub e distribui aos clientes inscritos
  await redisSub.psubscribe("market:ticks:*", "market:events:*");
  redisSub.on("pmessage", (_pattern, channel, message) => {
    if (channel.startsWith("market:ticks:")) {
      const symbol = channel.replace("market:ticks:", "");
      const subscribers = subscriptionsBySymbol.get(symbol);
      if (subscribers && subscribers.size > 0) {
        for (const socket of subscribers) {
          if (socket.readyState === 1) { // OPEN
            socket.send(message);
          }
        }
      }
    } else if (channel.startsWith("market:events:")) {
      // Broadcast de eventos de liquidação
      const symbol = channel.replace("market:events:", "");
      const subscribers = subscriptionsBySymbol.get(symbol);
      if (subscribers && subscribers.size > 0) {
        for (const socket of subscribers) {
          if (socket.readyState === 1) {
            socket.send(message);
          }
        }
      }
    }
  });

  app.get("/ws", { websocket: true }, (socket, req) => {
    // Interceptação de Geoblocking e Risco Regulatório no Handshake WSS
    const rawCountry = req.headers["cf-ipcountry"] || req.headers["x-country-code"] || req.headers["x-test-country"];
    const code = (rawCountry && typeof rawCountry === "string") ? rawCountry.trim().toUpperCase() : "BR";

    // Brasil é 100% livre: aceita conexão incondicionalmente
    if (code === "BR") {
      // Conexão permitida sem bloqueio
    } else if ((RED_ZONE_COUNTRIES as readonly string[]).includes(code)) {
      socket.close(4403, "Red zone regulatory block: retail trading prohibited");
      return;
    } else {
      const allowedCountries = ["BR", "MX", "CO", "AR", "CL", "PE"];
      if (/^[A-Z]{2}$/.test(code) && !allowedCountries.includes(code)) {
        socket.close(4403, "Geo-blocked: region not supported");
        return;
      }
    }

    let isAuthenticated = false;
    let currentUserId: string | null = null;
    const clientSubscriptions = new Set<string>();

    let pongTimeoutTimer: any = null;
    const HEARTBEAT_INTERVAL_MS = 30000;
    const HEARTBEAT_TIMEOUT_MS = 5000;

    const pingInterval = setInterval(() => {
      if (socket.readyState === 1) {
        socket.send(JSON.stringify({ type: "ping" }));

        // Timeout estrito de 5s para o recebimento do pong (RFC 6455 / Padrão Indústria)
        if (pongTimeoutTimer) clearTimeout(pongTimeoutTimer);
        pongTimeoutTimer = setTimeout(() => {
          socket.close(4408, "Heartbeat timeout");
          clearInterval(pingInterval);
        }, HEARTBEAT_TIMEOUT_MS);
      }
    }, HEARTBEAT_INTERVAL_MS);

    // Timeout de 5s para autenticação na primeira mensagem (S-02)
    const authTimeout = setTimeout(() => {
      if (!isAuthenticated) {
        socket.close(4401, "Authentication timeout");
      }
    }, 5000);

    socket.on("message", async (raw: any) => {
      try {
        const msg = JSON.parse(raw.toString());

        if (msg.type === "pong") {
          if (pongTimeoutTimer) {
            clearTimeout(pongTimeoutTimer);
            pongTimeoutTimer = null;
          }
          return;
        }

        // 1. Mensagem de Autenticação
        if (msg.type === "auth") {
          clearTimeout(authTimeout);
          const authData = await verifyToken(msg.token);
          if (!authData) {
            socket.close(4401, "Invalid or expired token");
            return;
          }

          currentUserId = authData.userId;
          // Limite de 5 conexões por usuário compartilhado no Redis (V-11)
          let allowed = true;
          try {
            const count = await redisClient.incr(`ws:conn:${currentUserId}`);
            if (count === 1) {
              await redisClient.expire(`ws:conn:${currentUserId}`, 60);
            } else if (count > 5) {
              await redisClient.decr(`ws:conn:${currentUserId}`);
              allowed = false;
            } else {
              await redisClient.expire(`ws:conn:${currentUserId}`, 60);
            }
          } catch {
            const userConns = activeConnectionsByUser.get(currentUserId) || new Set();
            if (userConns.size >= 5) allowed = false;
          }

          if (!allowed) {
            socket.close(4429, "Too many concurrent connections for user");
            return;
          }

          const userConns = activeConnectionsByUser.get(currentUserId) || new Set();
          userConns.add(socket);
          activeConnectionsByUser.set(currentUserId, userConns);
          isAuthenticated = true;

          socket.send(JSON.stringify({ type: "auth_ok", user_id: currentUserId }));
          return;
        }

        if (!isAuthenticated) {
          socket.close(4401, "Must authenticate first");
          return;
        }

        // 2. Mensagem de Subscrição de Ativo (Suporta símbolo único ou lote multiplexado)
        if (msg.type === "subscribe") {
          const rawSymbols: string[] = Array.isArray(msg.symbols) ? msg.symbols : (msg.symbol ? [msg.symbol] : []);
          if (rawSymbols.length === 0) return;

          if (clientSubscriptions.size + rawSymbols.length > 10) {
            socket.send(JSON.stringify({ type: "error", message: "Max 10 symbol subscriptions per connection" }));
            return;
          }

          for (const symbol of rawSymbols) {
            clientSubscriptions.add(symbol);
            if (!subscriptionsBySymbol.has(symbol)) {
              subscriptionsBySymbol.set(symbol, new Set());
            }
            subscriptionsBySymbol.get(symbol)!.add(socket);

            // Se solicitou catch-up por lastSequence (M-06)
            if (msg.lastSequence !== undefined) {
              const catchup = await catchupHandler.getCatchupTicks(symbol, BigInt(msg.lastSequence));
              if (catchup.resyncRequired) {
                socket.send(JSON.stringify({ type: "resync_required", symbol }));
              } else if (catchup.ticks.length > 0) {
                socket.send(JSON.stringify({ type: "catchup_ticks", symbol, ticks: catchup.ticks }));
              }
            }

            socket.send(JSON.stringify({ type: "subscribed", symbol }));
          }
          return;
        }

        // 3. Unsubscribe (Suporta símbolo único ou lote multiplexado)
        if (msg.type === "unsubscribe") {
          const rawSymbols: string[] = Array.isArray(msg.symbols) ? msg.symbols : (msg.symbol ? [msg.symbol] : []);
          for (const symbol of rawSymbols) {
            clientSubscriptions.delete(symbol);
            subscriptionsBySymbol.get(symbol)?.delete(socket);
            socket.send(JSON.stringify({ type: "unsubscribed", symbol }));
          }
          return;
        }
      } catch (err) {
        socket.send(JSON.stringify({ type: "error", message: "Malformed message" }));
      }
    });

    socket.on("close", () => {
      clearInterval(pingInterval);
      if (pongTimeoutTimer) clearTimeout(pongTimeoutTimer);
      clearTimeout(authTimeout);

      if (currentUserId) {
        redisClient.decr(`ws:conn:${currentUserId}`).catch(() => {});
        const userConns = activeConnectionsByUser.get(currentUserId);
        if (userConns) {
          userConns.delete(socket);
          if (userConns.size === 0) {
            activeConnectionsByUser.delete(currentUserId);
          }
        }
      }

      for (const symbol of clientSubscriptions) {
        subscriptionsBySymbol.get(symbol)?.delete(socket);
      }
    });
  });

  try {
    await app.listen({ port: PORT, host: HOST });
    console.log(`[WebSocketGateway] Listening on ws://${HOST}:${PORT}/ws`);
  } catch (err) {
    console.error("[WebSocketGateway] Startup error:", err);
    process.exit(1);
  }
}

main();

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { CatchupHandler } from "../src/handlers/catchup-handler.js";

describe("CatchupHandler (lastSequence Resync Protocol)", () => {
  it("returns no ticks when client is already at latest sequence", async () => {
    const mockRedis = {
      xrevrange: async () => [
        ["entry-1", ["symbol", "SYNTH_VOL_50", "sequence", "500", "price", "1.48520", "ts", new Date().toISOString()]]
      ]
    };

    const handler = new CatchupHandler(mockRedis as any);
    const result = await handler.getCatchupTicks("SYNTH_VOL_50", 500n);

    assert.equal(result.resyncRequired, false);
    assert.equal(result.ticks.length, 0);
  });

