      method: "POST",
      url: "/api/v1/test-order",
      headers: { "cf-ipcountry": "BR" }
    });
    assert.strictEqual(res.statusCode, 201);
    const body = JSON.parse(res.body);
    assert.strictEqual(body.currency_ledger, "USD", "Ledger contábil opera 100% em USD");
  });
});

