// Teste E2: Distribuição Fan-out pelo WebSocket Gateway
// Cada VU simula um usuário autêntico abrindo 1 conexão WebSocket única e assinando 4 pares sorteados.
// Limite: 5 conexões/user, 10 pares/conexão.
// Critério de reprovação: Latência p95 > 500ms, erro WS > 1%.

const wsUrl = __ENV.WS_URL || 'ws://localhost:3001/ticks';
const wsConnected = new Rate('ws_connected_rate');
const tickDeliveryLatency = new Trend('tick_delivery_latency_ms');

const AVAILABLE_PAIRS = [
  'EURUSD_OTC', 'BTCUSD_OTC', 'SYNTH_VOL_50', 'XAUUSD_OTC',
  'GBPUSD_OTC', 'ETHUSD_OTC', 'GBPJPY_OTC', 'USOIL_OTC'
];

export const options = {
  scenarios: {
    ws_fanout_ramp: {
      executor: 'ramping-vus',
      startVUs: 10,
      stages: [
        { duration: '1m', target: 50 },
        { duration: '2m', target: 100 },
        { duration: '2m', target: 250 },
        { duration: '2m', target: 500 },
      ],
      gracefulRampDown: '10s',
    },
  },
  thresholds: {
    ws_connected_rate: ['rate>0.99'],
    tick_delivery_latency_ms: ['p(95)<500'], // Latência tick-to-client p95 < 500ms
  },
};

export default function () {
  // Sorteia 4 pares distintos para este usuário
  const shuffled = [...AVAILABLE_PAIRS].sort(() => 0.5 - Math.random());
  const selectedPairs = shuffled.slice(0, 4);

  const res = ws.connect(wsUrl, {}, function (socket) {
    socket.on('open', function () {
      wsConnected.add(true);
      // Assina os 4 pares sorteados em lote na mesma conexão única
      for (let i = 0; i < selectedPairs.length; i++) {
        socket.send(JSON.stringify({ type: 'subscribe', symbol: selectedPairs[i] }));
      }
    });

    socket.on('message', function (data) {
      try {
        const msg = JSON.parse(data);
        if (msg.type === 'tick' && msg.ts) {
          const latency = Date.now() - Date.parse(msg.ts);
          if (latency >= 0) {
            tickDeliveryLatency.observe(latency);
          }
        }
      } catch {
        // Ignora frames não-JSON
      }
    });

    socket.on('close', function () {
      // Conexão encerrada
    });

    // Mantém a conexão aberta recebendo ticks durante a sessão
    socket.setTimeout(function () {
      socket.close();
    }, 30000);
  });

  check(res, { 'status is 101': (r) => r && r.status === 101 });
  sleep(1);
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { CSPRNGRandomSource } from "../../services/tick-engine/src/engine/ou-generator.js";

describe("NIST SP 800-22 Entropy & Randomness Tests", () => {
  it("passes Frequency Monobit Test for CSPRNG Box-Muller increments (p-value > 0.01)", () => {
    const rng = new CSPRNGRandomSource();

    const SAMPLE_SIZE = 50_000;
    let positiveCount = 0;
    let negativeCount = 0;

    for (let i = 0; i < SAMPLE_SIZE; i++) {
      const inc = rng.nextGaussian();
      if (inc >= 0) positiveCount++;
      else negativeCount++;
    }

    // Proporção esperada: 0.50 (50% positivos, 50% negativos)
    const proportion = positiveCount / SAMPLE_SIZE;
    const zScore = Math.abs((positiveCount - SAMPLE_SIZE / 2) / Math.sqrt(SAMPLE_SIZE / 4));

    // Para p-value > 0.01, zScore deve ser < 2.576
    assert.ok(zScore < 2.576, `Z-Score ${zScore} exceeds 2.576 (significant bias detected)`);
    assert.ok(proportion > 0.48 && proportion < 0.52, `Proportion ${proportion} outside expected range [0.48, 0.52]`);
  });

  it("passes Runs Test for sign sequence (detects clustering/cycles)", () => {
    const rng = new CSPRNGRandomSource();

    const SAMPLE_SIZE = 20_000;
    const signs: number[] = [];

    for (let i = 0; i < SAMPLE_SIZE; i++) {
      const inc = rng.nextGaussian();
      signs.push(inc >= 0 ? 1 : 0);
    }

    let runs = 1;
    let ones = signs[0] === 1 ? 1 : 0;
    for (let i = 1; i < SAMPLE_SIZE; i++) {
      if (signs[i] !== signs[i - 1]) runs++;
      if (signs[i] === 1) ones++;
    }

    const pi = ones / SAMPLE_SIZE;
    const expectedRuns = 2 * SAMPLE_SIZE * pi * (1 - pi) + 1;
    const stdDevRuns = Math.sqrt(
      (2 * SAMPLE_SIZE * pi * (1 - pi) * (2 * SAMPLE_SIZE * pi * (1 - pi) - 1)) / (SAMPLE_SIZE - 1)
    );

    const zScore = Math.abs((runs - expectedRuns) / stdDevRuns);
    assert.ok(zScore < 2.576, `Runs Z-Score ${zScore} exceeds 2.576`);
  });
});

