// Mock determinístico de Scheduler e RafChartUpdater
class MockRafScheduler {
  constructor() {
    this.nextId = 1;
    this.callbacks = new Map();
  }

  requestAnimationFrame(cb) {
    const id = this.nextId++;
    this.callbacks.set(id, cb);
    return id;
  }

  cancelAnimationFrame(id) {
    this.callbacks.delete(id);
  }

  flushFrame() {
    const pending = Array.from(this.callbacks.entries());
    this.callbacks.clear();
    for (const [id, cb] of pending) {
      cb(performance.now());
    }
    return pending.length;
  }

  getPendingCount() {
    return this.callbacks.size;
  }
}

class TestRafUpdater {
  constructor(scheduler) {
    this.scheduler = scheduler;
    this.pendingTick = null;
    this.rafId = null;
    this.isPaused = false;
    this.renderedCount = 0;
    this.droppedCount = 0;
  }

  push(tick, onRender) {
    if (this.pendingTick !== null) {
      this.droppedCount++;
    }
    this.pendingTick = tick;

    if (this.isPaused) return;

    if (this.rafId === null) {
      this.rafId = this.scheduler.requestAnimationFrame(() => {
        const target = this.pendingTick;
        this.pendingTick = null;
        this.rafId = null;
        if (target) {
          this.renderedCount++;
          onRender(target);
        }
      });
    }
  }

  pause() {
    this.isPaused = true;
    if (this.rafId !== null) {
      this.scheduler.cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }

  resume(onRender) {
    this.isPaused = false;
    if (this.pendingTick !== null && this.rafId === null) {
      this.rafId = this.scheduler.requestAnimationFrame(() => {
        const target = this.pendingTick;
        this.pendingTick = null;
        this.rafId = null;
        if (target) {
          this.renderedCount++;
          if (onRender) onRender(target);
        }
      });
    }
  }

  cancel() {
    if (this.rafId !== null) {
      this.scheduler.cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    this.pendingTick = null;
  }
}

