import { describe, it } from 'vitest';
import assert from 'node:assert/strict';

describe('V-11: Distributed WebSocket Connection Limit Across Gateways', () => {
  it('enforces max 5 connections per sub across multiple gateway instances using Redis counter with TTL', async () => {
    // Simulação de Redis compartilhado
    const redisStore = new Map<string, { val: number; expireAt: number }>();

    const redis = {
      async incr(key: string, ttlSeconds: number, maxLimit: number): Promise<number> {
        const now = Date.now();
        let entry = redisStore.get(key);
        if (!entry || entry.expireAt <= now) {
          entry = { val: 0, expireAt: now + ttlSeconds * 1000 };
        }
        entry.val += 1;
        entry.expireAt = now + ttlSeconds * 1000;
        redisStore.set(key, entry);

        if (entry.val > maxLimit) {
          entry.val -= 1; // Reverte se ultrapassou
          return -1; // Rejeitado
        }
        return entry.val;
      },
      async decr(key: string): Promise<number> {
        let entry = redisStore.get(key);
        if (!entry) return 0;
        entry.val -= 1;
        if (entry.val <= 0) {
          redisStore.delete(key);
          return 0;
        }
        return entry.val;
      },
      async expire(key: string, ttlSeconds: number): Promise<void> {
        let entry = redisStore.get(key);
        if (entry) {
          entry.expireAt = Date.now() + ttlSeconds * 1000;
        }
      },
      get(key: string): number {
        const entry = redisStore.get(key);
        if (!entry || entry.expireAt <= Date.now()) return 0;
        return entry.val;
      }
    };

    const userId = 'user-sub-abc-123';
    const redisKey = `ws:conn:${userId}`;

    // Simulação de duas instâncias do Gateway (Gateway A e Gateway B)
    class GatewayInstance {
      name: string;
      localConnections: Set<string> = new Set();
      constructor(name: string) { this.name = name; }

      async handleConnect(connId: string): Promise<{ success: boolean; code?: number }> {
        const count = await redis.incr(redisKey, 60, 5);
        if (count === -1) {
          return { success: false, code: 4408 };
        }
        this.localConnections.add(connId);
        return { success: true };
      }

      async handleClose(connId: string): Promise<void> {
        if (this.localConnections.has(connId)) {
          this.localConnections.delete(connId);
          await redis.decr(redisKey);
        }
      }

      // Simulação de Crash abrupto (kill -9) onde não há callback de close
      crash(): void {
        this.localConnections.clear();
      }
    }

    const gatewayA = new GatewayInstance('Gateway-Node-A');
    const gatewayB = new GatewayInstance('Gateway-Node-B');

    // 1. Conexões 1 e 2 no Gateway A
    const c1 = await gatewayA.handleConnect('conn-1');
    const c2 = await gatewayA.handleConnect('conn-2');
    assert.equal(c1.success, true);
    assert.equal(c2.success, true);
    assert.equal(redis.get(redisKey), 2);

    // 2. Conexões 3 e 4 no Gateway B
    const c3 = await gatewayB.handleConnect('conn-3');
    const c4 = await gatewayB.handleConnect('conn-4');
    assert.equal(c3.success, true);
    assert.equal(c4.success, true);
    assert.equal(redis.get(redisKey), 4);

    // 3. 5ª Conexão no Gateway A (limite exato)
    const c5 = await gatewayA.handleConnect('conn-5');
    assert.equal(c5.success, true);
    assert.equal(redis.get(redisKey), 5);

    // 4. 6ª Conexão no Gateway B (DEVE SER REJEITADA com código 4408)
    const c6 = await gatewayB.handleConnect('conn-6');
    assert.equal(c6.success, false);
    assert.equal(c6.code, 4408, '6ª conexão distribuída DEVE ser recusada com código 4408 (V-11)');
    assert.equal(redis.get(redisKey), 5, 'Contador não deve vazar acima do teto de 5');

    // 5. Fechamento normal da conexão 1 no Gateway A
    await gatewayA.handleClose('conn-1');
    assert.equal(redis.get(redisKey), 4);

    // 6. Nova tentativa da conexão 6 no Gateway B agora é aceita
    const c6Retry = await gatewayB.handleConnect('conn-6');
    assert.equal(c6Retry.success, true);
    assert.equal(redis.get(redisKey), 5);

    // 7. Simula Crash abrupto (kill -9) do Gateway B com 3 conexões
    gatewayB.crash();
    // Simula expiração do TTL após 60s
    const entry = redisStore.get(redisKey)!;
    entry.expireAt = Date.now() - 1000; // Força expiração

    assert.equal(redis.get(redisKey), 0, 'Após expiração do TTL de crash, slots de conexão são 100% liberados');
  });
});

import { describe, it } from "vitest";
import assert from "node:assert/strict";
import { formatCurrency, convertUSDMinorToDisplay, DisplayCurrencyCode } from "../../packages/shared/src/currency.ts";

describe("Subetapa 3 (Unit): Motor de Formatação e Conversão de Moedas", () => {
  it("1. Deve formatar corretamente as 6 moedas com seus símbolos e decimais", () => {
    // BRL (2 decimais)
    const brl = formatCurrency(55.5, "BRL", "pt-BR");
    assert(brl.includes("R$"), `BRL deve conter R$, recebido: ${brl}`);
    assert(brl.includes("55,50"), `BRL deve formatar com 2 decimais e vírgula, recebido: ${brl}`);

    // MXN (2 decimais)
    const mxn = formatCurrency(195.25, "MXN", "es-MX");
    assert(mxn.includes("Mex$"), `MXN deve conter Mex$, recebido: ${mxn}`);
    assert(mxn.includes("195.25") || mxn.includes("195,25"), `MXN formatado: ${mxn}`);

    // COP (0 decimais)
    const cop = formatCurrency(41500, "COP", "es-CO");
    assert(cop.includes("Col$"), `COP deve conter Col$, recebido: ${cop}`);
    assert(!cop.includes(",00") && !cop.includes(".00"), `COP não deve conter centavos, recebido: ${cop}`);

    // ARS (2 decimais)
    const ars = formatCurrency(9800.75, "ARS", "es-AR");
    assert(ars.includes("$"), `ARS deve conter $, recebido: ${ars}`);

    // CLP (0 decimais)
    const clp = formatCurrency(9400, "CLP", "es-CL");
    assert(clp.includes("CLP$"), `CLP deve conter CLP$, recebido: ${clp}`);
    assert(!clp.includes(",00") && !clp.includes(".00"), `CLP não deve conter centavos, recebido: ${clp}`);

    // PEN (2 decimais)
    const pen = formatCurrency(37.5, "PEN", "es-PE");
    assert(pen.includes("S/."), `PEN deve conter S/., recebido: ${pen}`);
  });

  it("2. Deve converter stake_minor (USD centavos) para exibição regional preservando precisão", () => {
    // US$ 10,00 = 1000 minor units
    const stakeUSDMinor = 1000;

    // BRL (taxa 5.50) -> R$ 55,00
    const brlResult = convertUSDMinorToDisplay(stakeUSDMinor, 5.50, "BRL", "pt-BR");
    assert.strictEqual(brlResult.amount, 55.00);
    assert(brlResult.formatted.includes("R$ 55,00"));

    // COP (taxa 4150.00) -> Col$ 41.500
    const copResult = convertUSDMinorToDisplay(stakeUSDMinor, 4150.00, "COP", "es-CO");
    assert.strictEqual(copResult.amount, 41500);
    assert(copResult.formatted.includes("Col$"));

    // CLP (taxa 940.00) -> CLP$ 9.400
    const clpResult = convertUSDMinorToDisplay(stakeUSDMinor, 940.00, "CLP", "es-CL");
    assert.strictEqual(clpResult.amount, 9400);
    assert(clpResult.formatted.includes("CLP$"));

    // PEN (taxa 3.75) -> S/. 37,50
    const penResult = convertUSDMinorToDisplay(stakeUSDMinor, 3.75, "PEN", "es-PE");
    assert.strictEqual(penResult.amount, 37.50);
    assert(penResult.formatted.includes("S/."));
  });

  it("3. Invariante Contábil D-18: O stake original permanece imutável como inteiro", () => {
    const rawStake = 2500; // US$ 25,00
    const converted = convertUSDMinorToDisplay(rawStake, 5.50, "BRL");
    assert.strictEqual(rawStake, 2500, "O valor base minor não pode ser mutado");
    assert.strictEqual(typeof rawStake, "number");
    assert(Number.isInteger(rawStake), "O valor de stake no ledger é estritamente inteiro");
  });
});

import { describe, it } from "vitest";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";

describe("Subetapa 6 (Unit): Dicionários de Tradução e Paridade i18n", () => {
  const ptPath = path.resolve("apps/web/src/i18n/locales/pt-BR.json");
  const esPath = path.resolve("apps/web/src/i18n/locales/es-ES.json");

  const ptJson = JSON.parse(fs.readFileSync(ptPath, "utf-8"));
  const esJson = JSON.parse(fs.readFileSync(esPath, "utf-8"));

  function getKeys(obj: any, prefix = ""): string[] {
    let keys: string[] = [];
    for (const key of Object.keys(obj)) {
      const fullPath = prefix ? `${prefix}.${key}` : key;
      if (typeof obj[key] === "object" && obj[key] !== null) {
        keys = keys.concat(getKeys(obj[key], fullPath));
      } else {
        keys.push(fullPath);
      }
    }
    return keys;
  }

  it("1. Deve existir paridade exata de chaves entre pt-BR e es-ES (zero chaves ausentes)", () => {
    const ptKeys = getKeys(ptJson).sort();
    const esKeys = getKeys(esJson).sort();

    assert.deepStrictEqual(
      ptKeys,
      esKeys,
      "Os arquivos de tradução pt-BR e es-ES devem ter 100% das mesmas chaves"
    );
  });

  it("2. Deve conter as 5 seções fundamentais de interface", () => {
    const expectedSections = ["app", "geoblock", "trade", "currencies", "tabs"];
    for (const sec of expectedSections) {
      assert(ptJson[sec], `Seção '${sec}' deve existir no pt-BR`);
      assert(esJson[sec], `Seção '${sec}' deve existir no es-ES`);
    }
  });

  it("3. Mensagem de Geoblock deve referenciar com exatidão os 6 países da Fase 2", () => {
    const ptCountries = ptJson.geoblock.countries;
    const esCountries = esJson.geoblock.countries;

    assert(ptCountries.includes("Brasil"));
    assert(ptCountries.includes("México") || ptCountries.includes("Mexico"));
    assert(ptCountries.includes("Colômbia") || ptCountries.includes("Colombia"));
    assert(ptCountries.includes("Argentina"));
    assert(ptCountries.includes("Chile"));
    assert(ptCountries.includes("Peru") || ptCountries.includes("Perú"));

    assert(esCountries.includes("Brasil"));
    assert(esCountries.includes("Chile"));
    assert(esCountries.includes("Argentina"));
  });
});

import { describe, it, expect } from "vitest";
import assert from "node:assert/strict";
import { GeoBlockService } from "../../services/api/src/services/geoblock.ts";
import { FeatureFlagsService } from "../../services/api/src/services/feature-flags.ts";

describe("Subetapa 2 (Unit): GeoBlockService & Header Anti-Spoofing", () => {
  it("1. Deve extrair país priorizando CF-IPCountry sanitizado", () => {
    const mockReq: any = {
      headers: {
        "cf-ipcountry": "br",
        "x-country-code": "us"
      }
    };
    const country = GeoBlockService.extractCountry(mockReq);
    assert.strictEqual(country, "BR", "Deve normalizar para maiúsculo e respeitar prioridade");
  });

  it("2. Deve sanitizar e rejeitar caracteres espúrios ou ataques de injeção no header", () => {
    const mockReqMalicious: any = {
      headers: {
        "cf-ipcountry": "BR' OR '1'='1"
      }
    };
    const country = GeoBlockService.extractCountry(mockReqMalicious);
    assert.strictEqual(country, "UNKNOWN", "Header malformado deve resultar em UNKNOWN");
  });

  it("3. Deve validar estritamente a allowlist dos 6 países da Fase 2", () => {
    const allowed = ["BR", "MX", "CO", "AR", "CL", "PE"];
    for (const c of allowed) {
      assert.strictEqual(GeoBlockService.isAllowed(c), true, `País ${c} deve ser permitido`);
    }

    const blocked = ["US", "GB", "DE", "FR", "RU", "CN", "CA", "ES", "IT"];
    for (const c of blocked) {
      assert.strictEqual(GeoBlockService.isAllowed(c), false, `País ${c} deve ser bloqueado`);
    }
  });

  it("4. Deve resolver o contexto geográfico completo e metadados para cada país", () => {
    const reqBR: any = { headers: { "cf-ipcountry": "BR" } };
    const ctxBR = GeoBlockService.resolveGeoContext(reqBR);
    assert.strictEqual(ctxBR.country, "BR");
    assert.strictEqual(ctxBR.allowed, true);
    assert.strictEqual(ctxBR.defaultCurrency, "BRL");
    assert.strictEqual(ctxBR.defaultLocale, "pt-BR");

    const reqMX: any = { headers: { "cf-ipcountry": "MX" } };
    const ctxMX = GeoBlockService.resolveGeoContext(reqMX);
    assert.strictEqual(ctxMX.country, "MX");
    assert.strictEqual(ctxMX.allowed, true);
    assert.strictEqual(ctxMX.defaultCurrency, "MXN");
    assert.strictEqual(ctxMX.defaultLocale, "es-MX");

    const reqUS: any = { headers: { "cf-ipcountry": "US" } };
    const ctxUS = GeoBlockService.resolveGeoContext(reqUS);
    assert.strictEqual(ctxUS.country, "US");
    assert.strictEqual(ctxUS.allowed, false, "EUA deve estar bloqueado na Fase 2");
  });
});

describe("Subetapa 2 (Unit): FeatureFlagsService com Cache & Fallback", () => {
  it("5. Deve retornar flags com fallback em memória seguro se banco e cache forem mockados", async () => {
    const mockPg: any = {
      query: async (sql: string, params: any[]) => {
        if (sql.includes("FROM countries WHERE code")) {
          return { rows: [{ is_active: true }] };
        }
        if (sql.includes("FROM country_feature_flags WHERE country_code")) {
          return { rows: [{ flag_key: "trading_enabled", enabled: true }] };
        }
        return { rows: [] };
      }
    };

    const memoryCache = new Map<string, string>();
    const mockRedis: any = {
      get: async (key: string) => memoryCache.get(key) || null,
      set: async (key: string, val: string) => { memoryCache.set(key, val); return "OK"; },
      del: async (key: string) => { memoryCache.delete(key); return 1; },
      publish: async () => 1
    };

    const service = new FeatureFlagsService(mockPg, mockRedis);

    // 1ª chamada: Cache Miss (consulta banco e popula cache)
    const flags1 = await service.getCountryFlags("BR");
    assert.strictEqual(flags1.trading_enabled, true);
    assert.strictEqual(memoryCache.has("broker:flags:country:BR"), true, "Chave deve estar gravada no Redis");

    // 2ª chamada: Cache Hit (retorna do cache)
    const flags2 = await service.getCountryFlags("BR");
    assert.strictEqual(flags2.trading_enabled, true);

    // Atualização de flag invalida o cache
    await service.setCountryFlag("BR", "trading_enabled", false);
    assert.strictEqual(memoryCache.has("broker:flags:country:BR"), false, "Cache deve ser invalidado após update");
  });

  it("6. Resiliência: Deve tolerar queda total do Redis e recorrer ao PostgreSQL sem lançar erro", async () => {
    const mockPg: any = {
      query: async (sql: string) => {
        if (sql.includes("FROM countries WHERE code")) return { rows: [{ is_active: true }] };
        if (sql.includes("FROM country_feature_flags WHERE country_code")) {
          return { rows: [{ flag_key: "otc_real_feed", enabled: true }] };
        }
        return { rows: [] };
      }
    };

    const brokenRedis: any = {
      get: async () => { throw new Error("ECONNREFUSED: Redis instance offline"); },
      set: async () => { throw new Error("ECONNREFUSED: Redis instance offline"); },
      del: async () => { throw new Error("ECONNREFUSED: Redis instance offline"); }
    };

    const service = new FeatureFlagsService(mockPg, brokenRedis);
    const flags = await service.getCountryFlags("MX");

    assert.strictEqual(flags.otc_real_feed, true, "Deve responder com dados do PostgreSQL mesmo com Redis caído");
  });
});

